-- Module 1: sat-essentials (26 sections, 3641 words) ------------
insert into public.sat_playbook_pages (id, product_id, parent_page_id, page_type, module_key, slug, title, summary, status, visibility, locale_code, sort_order, seo_title, seo_description, seo_keywords, published_at, metadata)
values (md5('schood-sat-pb-page:sat-essentials')::uuid, 'a8b41e2c-9a36-4caf-9bba-7212e35a8b8c'::uuid, null, 'module', 'sat-essentials', 'sat-essentials', 'SAT Essentials: How the Digital SAT Works', 'Start here. The digital SAT explained end to end: sections, modules, timing, adaptive routing, scoring, the eight content domains, Bluebook tools, and how to turn that knowledge into a preparation plan.', 'published', 'public', 'en', 1, 'Digital SAT Essentials: Format, Timing, Scoring and Domains | SAT Playbook', 'A complete orientation to the digital SAT in Bluebook: two sections, four modules, 98 questions in 134 minutes, two-stage adaptive scoring, the eight content domains and the tools you can use.', array['SAT', 'Digital SAT', 'Bluebook', 'SAT format', 'SAT scoring', 'adaptive SAT', 'SAT domains', 'SAT Playbook']::text[], '2026-10-24T00:00:00Z'::timestamptz, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1","original_slug":"sat-essentials","module_group":"format_overview","migration_group":"core","hero_kicker":"Module 1","word_count":3641,"section_count":26,"reading_minutes":18,"estimated_reading_minutes":18,"section_kinds":["rich_text","checklist","callout"],"related_practice":[{"label":"Today''s SAT practice session","url":"https://practice.sat.schood.online/today"},{"label":"Full SAT simulator","url":"https://sat.schood.online"},{"label":"Reading and Writing question bank","url":"https://practice.sat.schood.online/bank?section_type=reading_writing"},{"label":"Math question bank","url":"https://practice.sat.schood.online/bank?section_type=math"}],"last_verified":"2026-10-24","verification_status":"verified","editorial":"original-schood"}'::jsonb)
on conflict do nothing;

insert into public.sat_playbook_page_sections (id, page_id, block_type, heading, status, sort_order, content, metadata)
select md5('schood-sat-pb-section:sat-essentials:' || s.n)::uuid, p.id, s.block_type, s.heading, 'published', s.n, s.content, s.metadata
from public.sat_playbook_pages p
cross join (values
  (1, 'rich_text', 'Why This Module Matters', '{"markdown":"Most wasted SAT preparation comes from studying the wrong test. Students download old paper books, memorise strategies for long reading passages that no longer exist, or practise without a calculator because \"the first math section doesn''t allow one\". None of that matches the test you will sit.\n\nThe current SAT is a **digital, two-stage adaptive test** delivered in College Board''s Bluebook app. It is shorter than the old paper test, it uses many short passages instead of a few long ones, a calculator is allowed on every Math question, and your second module in each section depends on how you did in the first.\n\nThis module gives you an accurate map of that test. Every later module in the Playbook assumes you know what is here, so read it once carefully and come back to the tables whenever you plan your week.\n\n**By the end you should be able to explain the test to a friend in two minutes**, and you should know exactly which of the eight content domains to study first."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (2, 'checklist', 'What You Will Be Able to Do', '{"items":["Describe the two sections, four modules, question counts and timing of the digital SAT.","Explain what the two-stage adaptive design does and what it does not do.","Read a score report: total score, two section scores, percentiles and content domain bars.","Name the eight content domains and roughly how many questions each contributes.","Use the Bluebook tools that save time: mark for review, option eliminator, highlights and notes, the question menu, Desmos and the reference sheet.","Separate real SAT facts from common myths carried over from the paper test.","Pick a sensible starting point for your preparation and know which Playbook module to read next."]}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (3, 'rich_text', 'The Digital SAT in One Table', '{"markdown":"| Feature | Reading and Writing | Math |\n|---|---|---|\n| Order on test day | Section 1 | Section 2 (after the break) |\n| Modules | 2, separately timed | 2, separately timed |\n| Questions per module | 27 | 22 |\n| Time per module | 32 minutes | 35 minutes |\n| Section total | 54 questions, 64 minutes | 44 questions, 70 minutes |\n| Unscored pretest questions | 2 per module | 2 per module |\n| Question format | Four-option multiple choice | About 75% multiple choice, about 25% student-produced response |\n| Calculator | Not allowed | Allowed on every question (built-in Desmos or an approved handheld) |\n| Section score | 200–800 | 200–800 |\n\nThe whole test is **98 questions in 134 minutes (2 hours 14 minutes)**, with a **10-minute break** between the two sections. Your total score, from 400 to 1600, is simply the sum of the two section scores."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (4, 'rich_text', 'Section 1: Reading and Writing at a Glance', '{"markdown":"Reading and Writing combines what used to be two separate tests. Every question comes with its own short passage, between **25 and 150 words**, or a pair of short passages. Some passages include a table, bar graph or line graph. You answer **one question per passage**, then move to a completely new text.\n\nThat design has three consequences:\n\n- **Stamina matters less than focus.** You never hold a 700-word article in your head. You do have to switch topics 27 times in 32 minutes.\n- **Every word in the passage is there for a reason.** Short passages leave no room for filler, so details you skim past are often the evidence the question needs.\n- **Pacing averages about 71 seconds per question.** Some questions (conventions, transitions) take far less; some (inferences, quantitative evidence, cross-text) take more.\n\nPassages come from literature, history and social studies, the humanities and the sciences. You do not need outside knowledge of any of these subjects; the answer is always supported by the text.\n\nInside each module the questions appear in a fixed domain order: **Craft and Structure first, then Information and Ideas, then Standard English Conventions, then Expression of Ideas.** Questions testing the same skill are grouped and run from easier to harder within their group."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (5, 'rich_text', 'Section 2: Math at a Glance', '{"markdown":"Math covers four domains in each module, and across each module the questions run **from easiest to hardest**. Roughly 30% of Math questions are set in a context such as science, social studies or a real-world situation; the rest are pure math.\n\nAbout a quarter of the questions are **student-produced responses (SPR)**: there are no answer choices and you type your answer into an entry box. Bluebook shows a preview of what you typed so you can confirm it reads as you intended.\n\nA calculator is allowed for every Math question. Bluebook includes an embedded **Desmos calculator** with graphing and scientific modes, and you may bring your own approved handheld calculator instead or as well. A **reference sheet** with common area, volume and triangle formulas is available throughout both modules.\n\nThe average time per Math question is about **95 seconds**, but because difficulty rises through the module, the early questions should take well under a minute and the final few may deserve two or three."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (6, 'rich_text', 'How the Two-Stage Adaptive Design Works', '{"markdown":"Each section is divided into two equal-length modules.\n\n1. **Module 1** gives every student a broad mix of easy, medium and hard questions.\n2. When Module 1 ends, your performance on it decides which version of **Module 2** you receive: one that is, on average, **harder**, or one that is, on average, **easier** than Module 1.\n3. Your section score is based on your performance across **both** modules.\n\nThis is called multistage adaptive testing. It is different from question-by-question adaptive tests in one important way: **inside a module you can move freely**, skip ahead, mark questions and come back, as long as time remains. What you cannot do is return to Module 1 once it has ended.\n\nScoring uses item response theory. In plain terms, the score depends on which questions you answered correctly, how difficult those questions are, and the statistical likelihood that a response pattern reflects guessing. College Board states that two students with the same number of correct answers can receive different section scores.\n\nThe full strategy consequences of this design are covered in [Pacing and Adaptive Modules](https://playbook.sat.schood.online/pacing-and-adaptive-modules)."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (7, 'callout', 'Officially Known Versus Assumed', '{"label":"Separate fact from forum rumour","body":"College Board publishes the structure: two modules per section, a mixed first module, a harder or easier second module, scoring across both modules with item response theory, and two unscored pretest questions per module. College Board does not publish the exact number of correct answers that routes you to the harder module, the score tables for each route, or a list of which questions are pretest items. Treat any precise routing cut-off you read online as a guess, not a rule."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (8, 'rich_text', 'Pretest Questions', '{"markdown":"Each module contains **two pretest questions** that do not count toward your score. College Board uses them to evaluate questions for future tests. They look exactly like scored questions and are not labelled.\n\nWhat this means for you:\n\n- **You cannot identify them**, so never skip a question because it \"feels experimental\".\n- A strangely hard early question may be a pretest item or may simply be hard for you. Either way, give it a fair attempt, mark it if needed and move on.\n- Because 2 of 27 Reading and Writing questions and 2 of 22 Math questions are unscored, the scored counts are **25 per Reading and Writing module and 20 per Math module**."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (9, 'rich_text', 'Scoring: What the Numbers Mean', '{"markdown":"You receive three scores:\n\n| Score | Range | How it is built |\n|---|---|---|\n| Reading and Writing section score | 200–800 | Performance across both R&W modules |\n| Math section score | 200–800 | Performance across both Math modules |\n| Total score | 400–1600 | Sum of the two section scores |\n\nScores move in 10-point steps. The digital SAT no longer reports subscores or cross-test scores. Instead, the score report shows your performance in each of the **eight content domains** as a visual bar, along with the approximate number of questions each domain contributes. That domain view is the single most useful part of the report for planning study.\n\nThe report also gives **percentiles** and a **score range** based on the standard error of measurement, which reminds you that a single test score is an estimate. College Board''s college and career readiness benchmarks are **480 for Reading and Writing and 530 for Math**.\n\nFor a sense of scale, College Board''s published user-group percentiles place a total of **1000 at about the 47th percentile, 1200 at about the 75th and 1400 at about the 93rd**. The module [Score Goals and Study Plans](https://playbook.sat.schood.online/score-goals-and-study-plans) uses these tables to help you set a target."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (10, 'rich_text', 'No Penalty for Wrong Answers', '{"markdown":"There is no deduction for a wrong answer. College Board''s own guidance is that for most students it is better to guess than to leave a question blank, especially after eliminating one or two choices.\n\nMake this automatic:\n\n- **Never leave a multiple-choice question blank.** Before the module timer ends, every question should have an answer, even if it is a guess.\n- **For student-produced responses, enter your best estimate** rather than nothing. A reasonable attempt can be correct; an empty box cannot.\n- **Use the question menu** in the last two minutes to find any unanswered questions quickly."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (11, 'rich_text', 'The Eight Content Domains', '{"markdown":"| Section | Domain | Approximate share | Questions across the section |\n|---|---|---|---|\n| Reading and Writing | Craft and Structure | about 28% | 13–15 |\n| Reading and Writing | Information and Ideas | about 26% | 12–14 |\n| Reading and Writing | Standard English Conventions | about 26% | 11–15 |\n| Reading and Writing | Expression of Ideas | about 20% | 8–12 |\n| Math | Algebra | about 35% | 13–15 |\n| Math | Advanced Math | about 35% | 13–15 |\n| Math | Problem-Solving and Data Analysis | about 15% | 5–7 |\n| Math | Geometry and Trigonometry | about 15% | 5–7 |\n\nTwo lessons jump out of this table:\n\n1. **In Math, Algebra and Advanced Math are about 70% of the section.** A student who is weak on linear and quadratic work cannot compensate with geometry.\n2. **In Reading and Writing, the four domains are much closer in weight.** Conventions and Expression of Ideas together are close to half the section, and they are the most rule-based questions on the test, which makes them the fastest to improve for many students.\n\nEach domain has its own Playbook module with skills, worked examples, traps and drills."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (12, 'rich_text', 'How Questions Are Ordered Inside a Module', '{"markdown":"Order is information. Use it.\n\n**Reading and Writing:** Craft and Structure questions come first (words in context, text structure and purpose, cross-text connections), followed by Information and Ideas (central ideas, evidence, inferences), then Standard English Conventions, then Expression of Ideas (transitions and rhetorical synthesis). Similar questions are grouped and arranged from easier to harder within each group; conventions questions are arranged from easier to harder regardless of which rule they test.\n\n**Math:** questions from all four domains are mixed, and the whole module runs from easiest to hardest.\n\nPractical consequences:\n\n- In Reading and Writing, a hard question near the end of the Craft and Structure group does not mean the rest of the module is hard; the next group starts easier again.\n- In Math, the last five or so questions are usually the hardest. Protect time for them, but never at the cost of careless errors on the first fifteen.\n- In both sections, **conventions and transitions near the end of a Reading and Writing module are quick points**. Do not run out of time before you reach them."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (13, 'rich_text', 'Bluebook Tools You Should Master', '{"markdown":"Bluebook gives every student the same toolkit. Practise with all of it before test day so that none of it is new.\n\n| Tool | What it does | How to use it well |\n|---|---|---|\n| Timer | Counts down each module; can be hidden until 5 minutes remain | Hide it if it makes you anxious, but check it at planned checkpoints |\n| Mark for Review | Flags a question to revisit | Mark anything you guessed on, then return if time remains |\n| Option Eliminator | Crosses out choices you have ruled out | Cross out actively; it stops you rereading dead options |\n| Highlights and Notes | Highlights text and adds a personal note | Highlight the claim and the key evidence words in R&W passages |\n| Question Menu | Shows answered, unanswered and marked questions | Use it at the end of each module to catch blanks |\n| Line Reader | Helps you focus on one line of text | Useful if dense passages make you lose your place |\n| Calculator | Desmos, graphing and scientific modes | Learn the graphing techniques in the Desmos module |\n| Reference Sheet | Common Math formulas | Know what is on it so you never memorise those formulas twice |\n| Zoom | Keyboard or pinch zoom | Enlarge graphs and tables before reading values |\n\nYou get **one sheet of scratch paper** from the testing staff, and you may ask for more. You may not bring your own."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (14, 'rich_text', 'Calculator and Reference Sheet', '{"markdown":"The embedded Desmos graphing calculator changes how many questions can be solved. Systems of equations, intersections, zeros of a quadratic, regressions and many \"how many solutions\" questions can be answered visually in seconds if you know the steps.\n\nTwo cautions:\n\n- **A calculator does not replace setting up the problem.** Desmos cannot read a word problem for you.\n- **Some questions are faster by hand.** Simple linear equations, percent questions and most geometry reasoning are quicker on paper or in your head.\n\nThe reference sheet includes the area of a circle, rectangle and triangle, the circumference of a circle, the Pythagorean theorem, the 30-60-90 and 45-45-90 special right triangles, and the volumes of a rectangular box, cylinder, sphere, cone and pyramid. It also reminds you that a circle has 360 degrees or 2π radians of arc and that a triangle''s angles sum to 180 degrees. Anything else, such as the equation of a circle or the slope formula, you need to know yourself.\n\nThe full technique guide is [Desmos and Calculator Strategy](https://playbook.sat.schood.online/desmos-and-calculator-strategy)."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (15, 'rich_text', 'Student-Produced Responses in Brief', '{"markdown":"For SPR questions you type a number. The official rules, in summary:\n\n- Up to **5 characters for a positive answer** and **6 for a negative answer** (the minus sign counts).\n- Fractions and decimals are both accepted. If a fraction does not fit, enter its decimal.\n- If a decimal is too long, **truncate or round at the fourth digit**, so two-thirds can be entered as 2/3, .6666, .6667, 0.666 or 0.667, but not 0.66 or 0.67.\n- Enter mixed numbers as improper fractions or decimals: three and a half is 7/2 or 3.5, never \"3 1/2\".\n- Do not type symbols such as %, $ or commas.\n- If more than one answer is correct, enter just one.\n\nMost SPR errors are not math errors; they are entry errors. The two Math domain modules give more examples."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (16, 'rich_text', 'What Changed From the Paper SAT', '{"markdown":"If you have older books or advice, check them against this list before using them.\n\n- **Length:** 2 hours 14 minutes instead of about 3 hours.\n- **Passages:** many short texts with one question each, instead of a handful of long passages with ten or eleven questions each.\n- **Reading and Writing:** one combined section instead of separate Reading and Writing and Language tests.\n- **Calculator:** allowed on all of Math; there is no separate no-calculator portion.\n- **Adaptive:** Module 2 depends on Module 1.\n- **Scores:** no subscores or cross-test scores; domain performance appears instead.\n- **Word problems:** shorter on average.\n- **Essay:** not part of the SAT.\n\nSkills such as grammar rules, algebra and data reasoning still transfer from older materials. Pacing advice, passage strategies and full-test timing from the paper era do not."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (17, 'rich_text', 'Myths That Waste Preparation Time', '{"markdown":"**\"The first few questions of Module 1 count more.\"** College Board has not said so. Your score reflects your performance across both modules. Treat every question as worth full care.\n\n**\"If Module 2 feels easy, you have failed.\"** How a module feels is a poor signal. Students routinely misjudge difficulty, and every module contains a range of questions. Keep working.\n\n**\"You should leave hard questions blank.\"** There is no penalty for a wrong answer. Guess.\n\n**\"Desmos is cheating, so real students do it by hand.\"** It is an official tool provided to every test taker. Using it well is part of preparing.\n\n**\"Long reading practice is the best way to improve R&W.\"** General reading helps vocabulary and comprehension, but the test rewards precise reasoning about short texts. Practise the actual question types."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (18, 'rich_text', 'How to Read Your First Diagnostic', '{"markdown":"Take one full-length adaptive practice test early, either an official Bluebook practice test or the [Schood SAT simulator](https://sat.schood.online). Then read the result in this order:\n\n1. **Section scores.** Which section is further from your target?\n2. **Domain performance.** Within that section, which domain is weakest relative to its weight? A weak heavy domain (Algebra, Advanced Math, Craft and Structure) is the first priority.\n3. **Error type.** For each wrong answer, label it: did not know the content, misread the question, ran out of time, or made a careless slip. The fix for each is different.\n4. **Timing.** Did you finish each module? Where did the minutes go?\n\nDo not panic about a single number. One practice score is an estimate with a margin, and your first test in an unfamiliar format is usually the least representative."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (19, 'rich_text', 'A Four-Stage Preparation Arc', '{"markdown":"Most effective preparation follows the same arc, whatever the timeline.\n\n| Stage | Goal | Typical activities |\n|---|---|---|\n| 1. Orientation | Know the test | This module, one diagnostic test, tool practice in Bluebook |\n| 2. Skill building | Fix the biggest domain gaps | Domain modules, targeted question bank sets, error log |\n| 3. Integration | Combine skills under time | Timed module-length sets, a full test every one to two weeks |\n| 4. Sharpening | Peak on test day | Review of error log, light timed sets, test-day routine |\n\nThe length of each stage depends on your starting point and deadline. A four-week plan compresses stages 2 and 3; a twelve-week plan gives stage 2 the most time. Ready-made schedules are described in [Score Goals and Study Plans](https://playbook.sat.schood.online/score-goals-and-study-plans)."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (20, 'rich_text', 'Choosing a Starting Point', '{"markdown":"Use your diagnostic section scores to decide where to begin.\n\n- **Section score under about 500:** build foundations first. In Math, linear equations and functions; in Reading and Writing, the conventions rules and words in context. Untimed accuracy before speed.\n- **Section score about 500 to 650:** you know most content but lose points to traps and timing. Work through the domain modules'' traps and decision rules, and start timed sets.\n- **Section score above about 650:** gains come from the hardest questions in the harder Module 2. Focus on inference, cross-text, quantitative evidence, rhetorical synthesis, advanced functions, and data reasoning, plus flawless accuracy on the easy questions.\n\nThese bands are planning guides, not official categories."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (21, 'rich_text', 'Building a Weekly Rhythm', '{"markdown":"A sustainable week beats an occasional marathon. A balanced pattern for a student with about six to eight hours a week:\n\n- **Three short skill sessions** (30–45 minutes) on your weakest domain, using the Playbook module and a filtered question bank set.\n- **Two mixed timed sets** (one per section) of module length.\n- **One review session** for your error log: redo every missed question from scratch without looking at the explanation.\n- **One full-length test** every one to two weeks once you have covered your weakest domains.\n\nThe error log is the core of improvement. A missed question you never revisit is likely to be missed again."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (22, 'rich_text', 'How the Schood SAT Tools Fit Together', '{"markdown":"- **SAT Playbook** (this site): explains the test, the skills and the strategies, and builds a plan around your goal.\n- **SAT Practice** at practice.sat.schood.online: daily sessions and a question bank you can filter by section, domain and difficulty, with explanations.\n- **SAT Simulator** at sat.schood.online: full-length timed practice in a two-stage format, so you can rehearse pacing and see section estimates.\n\nThe intended loop is simple: read a module, practise that domain in the bank, test it under time, and let the results tell you what to read next."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (23, 'checklist', 'Before You Move On', '{"items":["I can state the number of questions and minutes in each module.","I know that I cannot return to a module once it ends, but I can move freely inside it.","I know Module 2 is harder or easier depending on Module 1, and that the exact routing rule is not published.","I will answer every question because there is no penalty for wrong answers.","I know the eight content domains and which ones carry the most weight.","I have opened Bluebook and tried the tools, including Desmos and the reference sheet.","I have taken, or scheduled, one full-length diagnostic test."]}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (24, 'rich_text', 'Frequently Asked Questions', '{"markdown":"### Is the SAT the same everywhere in the world?\nThe digital SAT has the same structure, timing and scoring wherever it is taken. Test dates, registration details and some ID rules vary by country, so check College Board''s pages for your location.\n\n### How long does the whole test take?\nThe testing time is 2 hours 14 minutes plus a 10-minute break. Check-in and instructions add time on the day: at a typical weekend morning sitting, check-in starts at 7:45 a.m. and standard-time testing ends around 10:45 to 11:00 a.m. Your admission ticket shows your actual times.\n\n### Can I go back to a question?\nYes, within the same module, as long as time remains. Once a module ends you cannot return to it.\n\n### Do hard questions count more?\nThe scoring model accounts for question difficulty, but College Board does not publish point values for individual questions. Your job is the same either way: get as many questions right as you can and guess on the rest.\n\n### Is there still an essay?\nNo. The SAT does not include an essay.\n\n### Where can I find official practice?\nBluebook includes full-length practice tests. College Board also partners with Khan Academy for free official practice."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (25, 'rich_text', 'Related Practice', '{"markdown":"- [Today''s practice session](https://practice.sat.schood.online/today): a short mixed set chosen for you.\n- [Reading and Writing question bank](https://practice.sat.schood.online/bank?section_type=reading_writing): filter by domain and difficulty.\n- [Math question bank](https://practice.sat.schood.online/bank?section_type=math): filter by domain and difficulty.\n- [SAT Simulator](https://sat.schood.online): a full-length timed test for your diagnostic."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (26, 'rich_text', 'Next Steps', '{"markdown":"1. Read [Pacing and Adaptive Modules](https://playbook.sat.schood.online/pacing-and-adaptive-modules) to turn the adaptive design into a timing plan.\n2. Take a diagnostic, then open the module for your weakest domain: [Information and Ideas](https://playbook.sat.schood.online/reading-writing-information-ideas), [Craft and Structure](https://playbook.sat.schood.online/reading-writing-craft-structure), [Expression of Ideas](https://playbook.sat.schood.online/reading-writing-expression-of-ideas), [Conventions](https://playbook.sat.schood.online/reading-writing-conventions), [Algebra](https://playbook.sat.schood.online/math-algebra), [Advanced Math](https://playbook.sat.schood.online/math-advanced-math), [Problem-Solving and Data Analysis](https://playbook.sat.schood.online/math-problem-solving-data-analysis) or [Geometry and Trigonometry](https://playbook.sat.schood.online/math-geometry-trigonometry).\n3. Set a target in [Score Goals and Study Plans](https://playbook.sat.schood.online/score-goals-and-study-plans).\n4. When your date is close, read the [Test Day Guide](https://playbook.sat.schood.online/test-day-guide)."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb)
) as s(n, block_type, heading, content, metadata)
where p.id = md5('schood-sat-pb-page:sat-essentials')::uuid
on conflict do nothing;

