-- Module 2: pacing-and-adaptive-modules (28 sections, 3481 words) ------------
insert into public.sat_playbook_pages (id, product_id, parent_page_id, page_type, module_key, slug, title, summary, status, visibility, locale_code, sort_order, seo_title, seo_description, seo_keywords, published_at, metadata)
values (md5('schood-sat-pb-page:pacing-and-adaptive-modules')::uuid, 'a8b41e2c-9a36-4caf-9bba-7212e35a8b8c'::uuid, null, 'module', 'pacing-and-adaptive-modules', 'pacing-and-adaptive-modules', 'Pacing and Adaptive Modules', 'How Module 1 routes you to a harder or easier Module 2, what College Board has and has not said about it, and the pacing plans, checkpoints, two-pass method and guessing rules that follow from the design.', 'published', 'public', 'en', 2, 'Digital SAT Adaptive Modules and Pacing Strategy | SAT Playbook', 'Understand two-stage adaptive routing on the digital SAT without myths, then use module-by-module time budgets, checkpoints, mark-and-move rules and guessing strategy.', array['SAT', 'Digital SAT', 'adaptive', 'Module 2', 'SAT pacing', 'SAT timing', 'Bluebook', 'SAT strategy']::text[], '2026-10-24T00:00:00Z'::timestamptz, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1","original_slug":"pacing-and-adaptive-modules","module_group":"scoring_engine","migration_group":"core","hero_kicker":"Module 2","word_count":3481,"section_count":28,"reading_minutes":17,"estimated_reading_minutes":17,"section_kinds":["rich_text","checklist","callout"],"related_practice":[{"label":"Full SAT simulator (timed modules)","url":"https://sat.schood.online"},{"label":"Today''s practice session","url":"https://practice.sat.schood.online/today"},{"label":"Hard Math questions","url":"https://practice.sat.schood.online/bank?section_type=math&difficulty=hard"},{"label":"Hard Reading and Writing questions","url":"https://practice.sat.schood.online/bank?section_type=reading_writing&difficulty=hard"}],"last_verified":"2026-10-24","verification_status":"verified","editorial":"original-schood"}'::jsonb)
on conflict do nothing;

insert into public.sat_playbook_page_sections (id, page_id, block_type, heading, status, sort_order, content, metadata)
select md5('schood-sat-pb-section:pacing-and-adaptive-modules:' || s.n)::uuid, p.id, s.block_type, s.heading, 'published', s.n, s.content, s.metadata
from public.sat_playbook_pages p
cross join (values
  (1, 'rich_text', 'Why This Module Matters', '{"markdown":"Two students with the same knowledge can finish the SAT with very different scores because one of them spends six minutes on a single question in Module 1 and the other does not. On the digital SAT, pacing is not only about finishing. It decides how much of your knowledge reaches the scoring model, and it shapes which Module 2 you see.\n\nThis module does two jobs. First, it explains the adaptive design accurately, separating what College Board has published from what students repeat on forums. Second, it turns that design into concrete pacing plans, checkpoints and decision rules for each section.\n\n**The headline:** do everything you can to bank the questions you know in Module 1, never let one question eat your time, and answer every question before the timer ends."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (2, 'checklist', 'What You Will Be Able to Do', '{"items":["Explain how Module 1 performance leads to a harder or easier Module 2.","State what College Board has officially said about routing and scoring, and what it has not.","Use a time budget and checkpoints for each Reading and Writing and Math module.","Apply a two-pass method with mark-for-review so that hard questions never block easy ones.","Decide in seconds whether to solve, skip, guess or return.","Guess intelligently on every unanswered question before time runs out.","Diagnose your own pacing problems from a practice test."]}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (3, 'rich_text', 'The Design in Four Facts', '{"markdown":"1. **Every section has two equal-length, separately timed modules.** Reading and Writing: 27 questions in 32 minutes per module. Math: 22 questions in 35 minutes per module.\n2. **Module 1 is the same kind of mixed module for everyone**: a broad range of easy, medium and hard questions.\n3. **Module 2 is routed.** Based on your Module 1 performance, you receive a second module that is, on average, either higher or lower in difficulty than Module 1.\n4. **Your section score uses both modules.** Scoring uses item response theory, which takes into account which questions you answered correctly, their difficulty, and the likelihood that a pattern of responses reflects guessing.\n\nThat is the whole published mechanism. Everything else is inference."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (4, 'callout', 'What College Board Has Not Published', '{"label":"Known unknowns","body":"College Board does not publish the number of correct answers needed to be routed to the harder Module 2, the score conversion for either route, the point value of any individual question, or which questions are the two unscored pretest items in each module. Precise claims such as \"you need 18 right to get the hard module\" or \"the easy module caps you at a fixed score\" are not official. Plan as if every question matters, because from your seat it does."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (5, 'rich_text', 'Reasonable Inferences From the Design', '{"markdown":"Some conclusions follow from how adaptive tests generally work, even though College Board does not spell them out. Treat them as sensible working assumptions, not rules.\n\n- **Module 1 accuracy has a double effect.** A correct answer there counts toward your score and also contributes to the routing decision.\n- **The highest section scores are likely to require the harder Module 2.** A lower-difficulty module contains fewer of the hard questions that distinguish very high performers. College Board has not published a cap, so do not treat any specific number as a ceiling.\n- **The easier Module 2 still matters a great deal.** If you are routed there, strong accuracy in Module 2 is how you raise your section score.\n- **Difficulty inside a module is spread, not uniform.** A harder Module 2 still contains some approachable questions; an easier one still contains some demanding ones."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (6, 'rich_text', 'Module 1 Strategy: Bank Every Point You Know', '{"markdown":"Module 1 is where careless errors hurt most, because they affect both the score and the route.\n\n**Rules for Module 1:**\n\n- **Slow down slightly on easy questions.** Read the final line of every question twice: what exactly is being asked?\n- **Do not let a hard question steal time from the rest.** If you are stuck after your time cap, pick your best answer, mark it, and move on.\n- **Use the full time.** If you finish early, return to marked questions, then recheck student-produced response entries and any question where you changed your answer.\n- **Never leave a question blank.** There is no penalty for wrong answers.\n\nThe trap to avoid is perfectionism: a student who spends four minutes on question 12 in Math Module 1 and then rushes questions 16 to 22 usually loses more points than the one question was worth."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (7, 'rich_text', 'Module 2 Strategy: Keep Working, Ignore the Feeling', '{"markdown":"When Module 2 begins, you will not be told which route you are on. Students often try to guess from how the first few questions feel. Do not.\n\n- **A hard-feeling Module 2 is not a problem.** It may mean you were routed to the harder module, which is what you wanted.\n- **An easy-feeling Module 2 is not a verdict.** Your perception of difficulty is unreliable, and the module still counts toward your score.\n- **The strategy does not change.** Same time budget, same two-pass method, same guessing rules.\n\nThere is no break between Module 1 and Module 2 within a section. When the Module 1 timer reaches zero, Bluebook moves you on automatically, and you cannot return. The 10-minute break comes between the two sections."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (8, 'rich_text', 'Reading and Writing Time Budget', '{"markdown":"32 minutes for 27 questions is about **71 seconds per question on average**, but the question types are not equal. Questions arrive in domain order: Craft and Structure, then Information and Ideas, then Standard English Conventions, then Expression of Ideas.\n\n| Question group | Typical position | Target time each | Notes |\n|---|---|---|---|\n| Words in context | Start of module | 45–60 s | Predict a word before reading choices |\n| Text structure and purpose, cross-text | Early | 60–90 s | Cross-text pairs take longest in this group |\n| Central ideas, evidence, inferences | Middle | 75–100 s | Quantitative evidence and inferences can run longer |\n| Conventions | Later | 30–50 s | Rule-based, fast when rules are solid |\n| Transitions, rhetorical synthesis | End | 30–60 s | Read the goal first on synthesis questions |\n\nThese are Schood planning targets, not official figures. The point is the shape: spend a little more in the first two groups, and **arrive at the conventions questions with roughly 10 to 12 minutes left** so the fast questions at the end are not rushed."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (9, 'rich_text', 'Reading and Writing Checkpoints', '{"markdown":"Use the timer at planned moments instead of watching it constantly.\n\n- **About 10 minutes in:** you should be finishing the Craft and Structure group or just starting Information and Ideas.\n- **About 20 to 22 minutes in:** you should be at or near the first conventions question.\n- **5 minutes left (Bluebook alerts you):** finish your current question, then make sure every remaining question has at least a guess.\n- **Last 60 seconds:** open the question menu and fill any blank.\n\nIf you are behind at a checkpoint, the fix is to apply your time caps more strictly on the remaining slow questions, not to rush conventions."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (10, 'rich_text', 'Math Time Budget', '{"markdown":"35 minutes for 22 questions is about **95 seconds per question on average**. Because Math questions run from easiest to hardest across the module, the budget should be front-light.\n\n| Questions | Target time | Running total |\n|---|---|---|\n| 1–8 | about 40–60 s each | about 7–8 minutes |\n| 9–15 | about 75–90 s each | about 17–18 minutes |\n| 16–22 | about 2–2.5 min each | 35 minutes |\n\nThe aim is to reach question 16 with **about 15 to 17 minutes left**. Those final questions are where Desmos techniques, careful setup and checking pay off. Again, these are planning targets; adjust them after your first two timed practice tests."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (11, 'rich_text', 'Math Checkpoints', '{"markdown":"- **Question 8 by about minute 8.** If you are slower, you are probably over-checking easy questions or not using Desmos where it is faster.\n- **Question 15 by about minute 18.**\n- **5-minute alert:** if marked questions remain, choose the one you are most likely to solve; guess the rest now.\n- **Last 60 seconds:** open the question menu, fill any blank multiple-choice questions, and type a best estimate into any empty student-produced response box."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (12, 'rich_text', 'The Two-Pass Method', '{"markdown":"Bluebook lets you move freely inside a module, so use two passes.\n\n**Pass 1:** answer every question in order. For each question you either solve it, or you hit your time cap. At the cap, choose your best answer (eliminate what you can first), mark it for review, and move on.\n\n**Pass 2:** with the remaining time, open the question menu and return to marked questions, starting with the ones you felt closest to solving.\n\nWhy this works: it guarantees you see every question, it puts an answer on every question in case time runs out, and it spends leftover minutes where they are most likely to convert into points.\n\n**Do not skip a question without answering it.** A blank marked question is a risk; an answered marked question is insurance."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (13, 'rich_text', 'Time Caps and the Stop Rule', '{"markdown":"A time cap is a promise you make before the test: \"I will not spend more than X on any single question in pass 1.\"\n\n| Section | Suggested pass-1 cap |\n|---|---|\n| Reading and Writing | about 2 minutes |\n| Math, questions 1–15 | about 2 minutes |\n| Math, questions 16–22 | about 3 minutes |\n\nSigns you should stop now, even before the cap:\n\n- You have reread the passage or problem twice and still cannot say what is being asked.\n- You are on your third different approach to the same Math problem.\n- You are choosing between two options and have no new evidence to separate them.\n\nWhen you stop, eliminate, pick, mark and move. Your future self in pass 2 often sees the question more clearly."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (14, 'rich_text', 'Guessing Rules', '{"markdown":"There is no deduction for wrong answers, and College Board advises that for most students guessing is better than leaving a question blank, especially after eliminating one or two choices.\n\n- **Eliminate first, then guess.** Cross out impossible options with the option eliminator. A guess among two choices is far better than a guess among four.\n- **Do not overthink a pure guess.** If you have no information, pick any letter and move on; spend the time elsewhere.\n- **For student-produced responses, estimate.** Use Desmos, a quick sketch or a rough calculation to enter a plausible value. An empty box earns nothing.\n- **Change answers only with a reason.** On review, change an answer when you find a specific error or new evidence, not because of a vague feeling."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (15, 'rich_text', 'Worked Scenario 1: Behind in Math Module 1', '{"markdown":"**Situation:** You reach question 14 of Math Module 1 with 13 minutes left. You are behind the checkpoint (question 15 by minute 18 means about 17 minutes left).\n\n**Decision:** You have 9 questions and 13 minutes, about 87 seconds each, and the hardest questions are still ahead.\n\n1. Tighten the cap to 90 seconds for questions 14 and 15.\n2. On questions 16 to 22, spend the first 20 seconds deciding whether you see a path. If you do, work it. If not, eliminate, guess, mark.\n3. At the 5-minute alert, ensure every question has an answer, then use the remaining time on the marked question you felt closest to.\n\n**Why:** finishing with every question answered, and two or three of the later questions solved properly, beats solving question 16 perfectly and guessing on 17 to 22 with no thought."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (16, 'rich_text', 'Worked Scenario 2: Ahead in Reading and Writing', '{"markdown":"**Situation:** You reach the first conventions question of Reading and Writing Module 1 with 15 minutes left and three questions marked from earlier.\n\n**Decision:** Do not rush back to the marked questions. Finish the module in order first.\n\n1. Work through conventions and Expression of Ideas at normal speed. They are quick, and accuracy here is worth protecting.\n2. With the time left, open the question menu and revisit the marked questions in order of how close you felt.\n3. On each revisit, reread the question stem first, then the passage, and look for the specific word or line that decides it.\n\n**Why:** extra time is valuable only when it converts into points. Easy questions answered carefully are the most reliable conversion."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (17, 'rich_text', 'Worked Scenario 3: A Strange Question Early On', '{"markdown":"**Situation:** Question 3 of Math Module 1 looks unexpectedly hard.\n\n**Decision:** Give it a normal attempt within your cap. If it does not open up, eliminate, guess, mark and move.\n\n**Why:** it might be a pretest question, it might be a topic you have not studied, or it might be easier than it looks after a second read. You cannot tell which, so treat it like any other hard question. Do not let it unsettle the next twenty."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (18, 'rich_text', 'Diagnosing Your Pacing From a Practice Test', '{"markdown":"After each timed practice test, fill in a short pacing audit:\n\n| Question | Answer |\n|---|---|\n| Did I answer every question in every module? | Yes / No |\n| Where was I at each checkpoint? | Write the question number at each check |\n| Which single question took longest, and was it correct? | |\n| How many questions did I mark, and how many did I fix in pass 2? | |\n| How many errors were careless (I knew how, but slipped)? | |\n| Did I run out of time in Math 16–22 or in R&W conventions? | |\n\n**Read the audit like this:**\n\n- **Many careless errors, finished early:** slow down on easy questions and reread the question stem.\n- **Ran out of time, few marked questions:** you are not applying time caps.\n- **Many marked questions, few fixed in pass 2:** your pass-1 guesses need better elimination, or the content needs study rather than more time.\n- **Time lost in the middle of R&W:** Information and Ideas questions need a clearer method; see that module."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (19, 'rich_text', 'Pacing Drills', '{"markdown":"Build pacing deliberately, not only by taking full tests.\n\n1. **Ten-question sprints.** Take 10 easy-to-medium Math questions with a 9-minute limit. Target: all correct, all finished.\n2. **Cap practice.** Do a set of 12 hard questions with a strict 2-minute cap each. Record how many you solved within the cap and how many you correctly guessed after elimination.\n3. **Checkpoint rehearsal.** Take a full Reading and Writing module and write the question number you are on at minutes 10 and 21.\n4. **Last-minute fill.** In practice, set a 60-second alarm before the end and rehearse opening the question menu and filling blanks.\n5. **Pass-2 conversion.** After a timed set, count how many marked questions you got right on revisit. If the number is low, spend pass-2 time on the closest question only."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (20, 'rich_text', 'Drill: Choose the Best Pacing Decision', '{"markdown":"Answer each, then check the next section.\n\n1. Math Module 1, question 6. You have spent 2 minutes 30 seconds and you are close. What do you do?\n2. Reading and Writing Module 2, 4 minutes left, 6 questions unanswered (all conventions). What do you do?\n3. Math Module 2, question 19. You see a path, but it is long. You have 9 minutes left and three marked questions. What do you do?\n4. You finish Reading and Writing Module 1 with 6 minutes left and no marked questions. What do you do?\n5. Math Module 1 ends; Module 2 question 1 looks very hard. What does this tell you?\n6. A student-produced response question has you completely stuck, with 1 minute left in the module. What do you enter?"}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (21, 'rich_text', 'Drill Answers and Explanations', '{"markdown":"1. **Finish only if you are genuinely one step away; otherwise pick your best answer, mark it and move on.** Question 6 should be a quick question; spending more than 3 minutes here borrows time from the hardest questions later.\n2. **Answer all six quickly.** Conventions are fast. Aim for about 30 to 40 seconds each, and make sure each has an answer before the timer hits zero.\n3. **Work question 19 if you can do it in about 3 minutes, but first make sure every remaining question has at least a guess.** Insurance first, then the best remaining opportunity.\n4. **Recheck the questions you were least sure about**, starting with any where you hesitated between two options. Do not change answers without a specific reason.\n5. **Nothing reliable.** Difficulty is spread across a module, and your sense of difficulty is a weak signal. Keep working at your normal pace.\n6. **A reasonable estimate.** Use the context or a quick Desmos graph to enter a plausible number in the correct format. A blank cannot be correct."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (22, 'rich_text', 'Common Pacing Traps', '{"markdown":"- **Hovering on question 1.** Nerves make the first question feel heavy. Start, answer, move.\n- **Checking every easy question three times.** Once carefully is enough; save checks for the end.\n- **Skipping without guessing.** If time runs out, unanswered questions are lost.\n- **Rushing conventions.** They are fast but still require reading the full sentence.\n- **Trying to detect the route.** It changes nothing about what you should do next.\n- **Ignoring the 5-minute alert.** That alert is your cue to secure answers on every question."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (23, 'rich_text', 'Level-Specific Priorities', '{"markdown":"**Section score under about 500:** your pacing problem is usually content, not speed. Use untimed practice to build accuracy first, then introduce the two-pass method. In timed tests, protect the easier first half of each Math module and the conventions at the end of each R&W module.\n\n**About 500 to 650:** you probably finish but lose points to traps and occasional over-long questions. Strict time caps and the stop rule will help most.\n\n**Above about 650:** your margin lies in the final third of the harder Module 2. Practise hard sets with time caps, and make your pass-2 time count by revisiting the question you are closest to, not the hardest one.\n\nThese ranges are Schood planning guides, not official bands."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (24, 'rich_text', 'Using the Break as Part of Your Pacing', '{"markdown":"The 10-minute break between Reading and Writing and Math is the only scheduled pause in the test, and it resets your pacing for the second half.\n\n- **Leave Reading and Writing behind.** Whatever happened in those 64 minutes is finished and cannot be changed. Do not replay questions in your head.\n- **Eat or drink something light and stand up.** A short walk and a snack help concentration in a 70-minute Math section.\n- **Rehearse your Math checkpoints once.** Question 8 by minute 8, question 15 by about minute 18, answers on everything at the 5-minute alert.\n- **Return on time.** Bluebook times each student individually, and the break timer keeps running. An unscheduled break later in the test costs testing time that is not added back."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (25, 'rich_text', 'Building a Personal Pacing Profile', '{"markdown":"The budgets in this module are starting points. After two or three timed tests, replace them with your own numbers.\n\n1. **Record time per question group** for one Reading and Writing module and one Math module. A simple note on your scratch paper of the clock at each checkpoint is enough.\n2. **Compare time with accuracy.** A group where you are slow and accurate needs practice for speed; a group where you are fast and inaccurate needs you to slow down.\n3. **Move minutes deliberately.** If conventions take you 25 seconds each with high accuracy, you have earned extra time for inferences or the last Math questions. Write the new budget down.\n4. **Retest the profile** every two weeks. As skills improve, the time you need for each group changes, and the profile should change with it.\n\n**A profile you wrote yourself is the one you will actually follow under pressure.**"}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (26, 'rich_text', 'Frequently Asked Questions', '{"markdown":"### Can I go back to Module 1 after it ends?\nNo. Within a module you can move freely while time remains. Once the module ends, you cannot return.\n\n### Is there a break between Module 1 and Module 2?\nNo. The modules within a section run back to back. The 10-minute break is between Reading and Writing and Math.\n\n### Should I deliberately do worse on Module 1 to get an easier Module 2?\nNo. That would lower your score. The harder route is where high scores come from.\n\n### Do the first questions count more than the last?\nCollege Board has not published question point values. The scoring model considers question difficulty, but you cannot use that to game the test. Answer every question as well as you can.\n\n### What if I finish a module very early?\nUse the time to review marked questions and recheck student-produced response entries. Finishing early with errors is a sign to slow down next time.\n\n### Does the timer keep running if Bluebook freezes?\nBluebook is designed so that work is saved and, if your device needs to restart, you can pick up where you left off without losing testing time. Tell the proctor immediately if anything goes wrong."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (27, 'rich_text', 'Related Practice', '{"markdown":"- [SAT Simulator](https://sat.schood.online): full-length timed practice with two-module sections, ideal for checkpoint rehearsal.\n- [Hard Math questions](https://practice.sat.schood.online/bank?section_type=math&difficulty=hard): practise time caps on the questions that end each module.\n- [Hard Reading and Writing questions](https://practice.sat.schood.online/bank?section_type=reading_writing&difficulty=hard): practise the stop rule.\n- [Today''s practice session](https://practice.sat.schood.online/today): short daily sets to keep pacing sharp."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (28, 'rich_text', 'Next Steps', '{"markdown":"1. If you have not yet, read [SAT Essentials](https://playbook.sat.schood.online/sat-essentials) for the full format.\n2. Learn the calculator shortcuts that save the most time in [Desmos and Calculator Strategy](https://playbook.sat.schood.online/desmos-and-calculator-strategy).\n3. Put your pacing plan into a schedule with [Score Goals and Study Plans](https://playbook.sat.schood.online/score-goals-and-study-plans).\n4. Rehearse the whole day with the [Test Day Guide](https://playbook.sat.schood.online/test-day-guide)."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb)
) as s(n, block_type, heading, content, metadata)
where p.id = md5('schood-sat-pb-page:pacing-and-adaptive-modules')::uuid
on conflict do nothing;

