-- Module 12: score-goals-and-study-plans (28 sections, 3142 words) ------------
insert into public.sat_playbook_pages (id, product_id, parent_page_id, page_type, module_key, slug, title, summary, status, visibility, locale_code, sort_order, seo_title, seo_description, seo_keywords, published_at, metadata)
values (md5('schood-sat-pb-page:score-goals-and-study-plans')::uuid, 'a8b41e2c-9a36-4caf-9bba-7212e35a8b8c'::uuid, null, 'module', 'score-goals-and-study-plans', 'score-goals-and-study-plans', 'Score Goals and Study Plans', 'Set an SAT target from real data: college requirements, College Board percentiles and benchmarks, and your own diagnostic. Then split it into section goals and choose a four-, eight- or twelve-week plan or a section-priority plan.', 'published', 'public', 'en', 12, 'How to Set an SAT Score Goal and Pick a Study Plan | SAT Playbook', 'Use official College Board percentiles, benchmarks and your diagnostic to set realistic SAT total and section targets, then match them to a structured study plan.', array['SAT', 'SAT score goal', 'SAT percentiles', 'SAT study plan', 'SAT target score', 'Digital SAT', 'SAT Playbook']::text[], '2026-10-24T00:00:00Z'::timestamptz, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1","original_slug":"score-goals-and-study-plans","module_group":"result_strategy","migration_group":"core","hero_kicker":"Module 12","word_count":3142,"section_count":28,"reading_minutes":16,"estimated_reading_minutes":16,"section_kinds":["rich_text","checklist","callout"],"related_practice":[{"label":"Take a diagnostic in the SAT simulator","url":"https://sat.schood.online"},{"label":"Today''s practice session","url":"https://practice.sat.schood.online/today"},{"label":"SAT Practice study plan","url":"https://practice.sat.schood.online/plan"}],"last_verified":"2026-10-24","verification_status":"verified","editorial":"original-schood"}'::jsonb)
on conflict do nothing;

insert into public.sat_playbook_page_sections (id, page_id, block_type, heading, status, sort_order, content, metadata)
select md5('schood-sat-pb-section:score-goals-and-study-plans:' || s.n)::uuid, p.id, s.block_type, s.heading, 'published', s.n, s.content, s.metadata
from public.sat_playbook_pages p
cross join (values
  (1, 'rich_text', 'Why This Module Matters', '{"markdown":"\"I want a high score\" is not a goal. \"I need 1350, with at least 680 in Math, by the October test\" is. A precise target changes everything that follows: which domains you study, how many hours a week you need, which plan you choose and when you should book the test.\n\nThis module shows you how to set that target from real information rather than guesswork: the requirements of the colleges and scholarships you care about, College Board''s published percentiles and benchmarks, and your own diagnostic result. It then shows how to split a total into section goals and how to pick one of the Playbook''s plan templates.\n\n**One principle runs through all of it: use measured data, and treat every score as a range.**"}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (2, 'checklist', 'What You Will Be Able to Do', '{"items":["Find the score range that matters for each of your target colleges or programmes.","Read College Board''s percentile tables and benchmarks correctly.","Turn a diagnostic into a realistic baseline range instead of a single number.","Split a total score target into Reading and Writing and Math targets.","Choose between the four-week, eight-week and twelve-week plans and the section-priority plans.","Track progress with a measurement routine and know when to adjust the target."]}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (3, 'rich_text', 'Step 1: Start With Where You Are Applying', '{"markdown":"Your target should come from the places that will read your score.\n\n1. **List your colleges or programmes.** Include reach, match and likely options, and any scholarship with a score requirement.\n2. **Find each one''s published score information.** Many universities publish the middle 50% range of admitted or enrolled students (the 25th and 75th percentile scores) on their admissions pages or in their Common Data Set. Scholarships and foundation programmes often publish a minimum.\n3. **Check the score-use policy.** Some colleges superscore, some consider your highest single sitting, some require all scores, and some are test-optional or test-required. The [Retake and Superscore Strategy](https://playbook.sat.schood.online/retake-and-superscore-strategy) module explains each.\n4. **Write the numbers down from the source.** Do not rely on ranking websites or friends'' memories; requirements change from year to year.\n\n**A practical rule:** aim at or above the 75th percentile of your most important target. A score in the middle of a range keeps you competitive; a score above it makes the score a strength."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (4, 'rich_text', 'Step 2: Understand What Scores Mean Nationally', '{"markdown":"College Board publishes two kinds of percentile ranks:\n\n- **User group percentiles** are based on the actual SAT scores of students who graduated in the past three school years. This is the comparison most useful to applicants.\n- **Nationally representative percentiles** come from a research study of U.S. 11th and 12th graders, weighted to represent all students in those grades, including those who do not usually take the SAT.\n\nA percentile tells you the percentage of the comparison group scoring **at or below** your score. A 75th percentile score means about 75% of that group scored the same or lower."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (5, 'rich_text', 'Official Total Score Percentiles', '{"markdown":"Selected rows from College Board''s published SAT percentile table:\n\n| Total score | User group percentile | Nationally representative percentile |\n|---|---|---|\n| 1550 | 99 | 99+ |\n| 1500 | 97 | 99 |\n| 1450 | 95 | 99 |\n| 1400 | 93 | 97 |\n| 1350 | 89 | 94 |\n| 1300 | 85 | 91 |\n| 1250 | 80 | 86 |\n| 1200 | 75 | 81 |\n| 1150 | 69 | 74 |\n| 1100 | 62 | 67 |\n| 1050 | 55 | 58 |\n| 1000 | 47 | 48 |\n| 900 | 32 | 29 |\n| 800 | 17 | 14 |\n\n**How to use it:** look up your diagnostic and your target. Moving from 1100 to 1250 means moving from about the 62nd to about the 80th user-group percentile. At the top, small score differences represent large percentile differences in reverse: 1450 and 1550 are only 4 user-group percentile points apart, but those 100 points are extremely hard won."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (6, 'rich_text', 'Official Section Score Percentiles', '{"markdown":"User group percentiles for section scores:\n\n| Section score | Reading and Writing | Math |\n|---|---|---|\n| 750 | 98 | 95 |\n| 700 | 92 | 91 |\n| 650 | 84 | 84 |\n| 600 | 72 | 75 |\n| 550 | 59 | 64 |\n| 500 | 43 | 50 |\n| 450 | 29 | 37 |\n| 400 | 16 | 21 |\n\n**Notice that the same section score can sit at different percentiles in the two sections.** A 500 in Math is about the 50th user percentile; a 500 in Reading and Writing is about the 43rd. At the top, a 750 in Math is the 95th percentile while a 750 in Reading and Writing is the 98th. This is one reason students targeting very high totals often find more room in Math."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (7, 'rich_text', 'How the Class of 2025 Scored', '{"markdown":"College Board''s 2025 Total Group annual report summarises the SAT results of about **2.0 million students in the class of 2025** (each student counted once, using the most recent score). The mean total score was **1029**, with a mean of **521** in Reading and Writing and **508** in Math.\n\n| Total score band | Share of class of 2025 test takers |\n|---|---|\n| 1400–1600 | 7% |\n| 1200–1390 | 18% |\n| 1000–1190 | 28% |\n| 800–990 | 30% |\n| 600–790 | 14% |\n| 400–590 | 3% |\n\nThis is a different view from the percentile table (one graduating class rather than three), but the picture is consistent: **a total of 1200 or more puts you in roughly the top quarter**, and 1400 or more in the top 7% or so."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (8, 'rich_text', 'College Readiness Benchmarks', '{"markdown":"College Board''s college and career readiness benchmarks are **480 in Reading and Writing and 530 in Math**. They are set to predict a 75% likelihood of earning a C or higher in a related first-semester, credit-bearing college course.\n\nThe benchmarks are not admission cut-offs. They are a useful floor for planning: if a section is below its benchmark, closing that gap is usually the most efficient first step, because it means core skills in that section still need work."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (9, 'rich_text', 'Step 3: Turn Your Diagnostic Into a Range', '{"markdown":"Take one full-length adaptive practice test (Bluebook or the [Schood SAT simulator](https://sat.schood.online)) under real conditions. Then treat the result as a range, not a point.\n\n- College Board''s own score reports show a **score range** around each score, derived from the standard error of measurement, to show how much a score would likely vary if you took a different administration under identical conditions.\n- Your first test in a new format often underestimates you slightly, because tools and pacing are unfamiliar.\n- If you have two practice tests, use both. The average is a better baseline than either one.\n\n**Baseline example:** two practice totals of 1130 and 1170 give a working baseline of about 1150, and the next test could reasonably land anywhere around that level. Plan from the baseline, not from your best or worst day."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (10, 'rich_text', 'Step 4: Split the Total Into Section Targets', '{"markdown":"A total target is easier to work toward when it becomes two section targets. Three ways to split it:\n\n1. **Even split.** Add half of the gap to each section. Simple, and reasonable when both sections are similar.\n2. **Strength-led split.** Put more of the gap on the section with more room above you in the percentile tables or where your diagnostic shows weak but learnable domains.\n3. **Requirement-led split.** If a programme cares about one section (for example, a Math minimum for engineering or a scholarship''s section cut-off), set that section target first and fill the rest.\n\n**Check each section target against your domain results.** A Math target that needs big gains while Algebra and Advanced Math are already strong may be harder to reach than one that needs the same gain with weak Algebra, because Algebra and Advanced Math together make up about 70% of Math."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (11, 'rich_text', 'Worked Example 1: A Balanced Target', '{"markdown":"**Profile (fictional):** baseline Reading and Writing 560, Math 540, total 1100. Main target university''s middle 50% is 1250 to 1380 (taken from its admissions page). Twelve weeks until the test.\n\n**Target:** at or near the 75th percentile of that range: about 1350. Gap: 250 points.\n\n**Split:** both sections are mid-range. Domain results show weak Advanced Math and weak Expression of Ideas. The student sets Math 690 (+150) and Reading and Writing 660 (+100), total 1350.\n\n**Plan:** twelve-week foundation, with the first four weeks weighted toward Advanced Math and Expression of Ideas.\n\n**Why it is sensible:** the larger Math gain is matched to a large-weight weak domain, and the timeline is long enough to rebuild skills rather than only practise."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (12, 'rich_text', 'Worked Example 2: A Short Runway', '{"markdown":"**Profile (fictional):** baseline Reading and Writing 640, Math 600, total 1240. Target scholarship minimum 1300. Four weeks.\n\n**Target:** 1320, a small cushion above the minimum. Gap: 80 points.\n\n**Split:** Reading and Writing 660 (+20), Math 660 (+60). Domain results show careless errors in Algebra and slow Desmos use.\n\n**Plan:** four-week sprint. The fastest gains are accuracy on easy and medium Math, Desmos techniques for systems and quadratics, and conventions rules.\n\n**Why it is sensible:** in four weeks you sharpen skills you already have; you rarely rebuild a whole domain."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (13, 'rich_text', 'Worked Example 3: One Section Lags', '{"markdown":"**Profile (fictional):** baseline Reading and Writing 470, Math 650, total 1120. Target 1250. Eight weeks.\n\n**Target:** Reading and Writing 590 (+120), Math 660 (+10), total 1250.\n\n**Plan:** reading-writing-priority plan. Reading and Writing is below the 480 benchmark, so the plan starts with conventions rules and words in context, which are learnable and appear in every module, then builds toward evidence and inference questions.\n\n**Why it is sensible:** the gap is concentrated in one section and in skills that respond well to structured study, while Math is maintained with a lighter weekly set."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (14, 'rich_text', 'The Playbook Plan Templates', '{"markdown":"The Playbook includes five plan templates. Each one is a week-by-week schedule that links to the domain modules here and to sets in SAT Practice and the simulator.\n\n| Plan | Best for | Shape |\n|---|---|---|\n| [Four-week sprint](https://playbook.sat.schood.online/plans/four-week-sprint) | A test date about a month away | Diagnostic, two weeks of targeted skill work, one week of timed integration, a taper week |\n| [Eight-week standard](https://playbook.sat.schood.online/plans/eight-week-standard) | Most students with two months | Alternating skill weeks and timed weeks, a full test every two weeks |\n| [Twelve-week foundation](https://playbook.sat.schood.online/plans/twelve-week-foundation) | Larger gaps or a section below its benchmark | Longer skill-building phase before regular full tests |\n| [Math priority](https://playbook.sat.schood.online/plans/math-priority) | Math far below its target | Most weekly hours on Algebra and Advanced Math, maintenance R&W |\n| [Reading and Writing priority](https://playbook.sat.schood.online/plans/reading-writing-priority) | Reading and Writing far below its target | Conventions and words in context first, then evidence and inferences, maintenance Math |\n\nPlan templates open from your Playbook dashboard, which personalises them using your goal, test date and diagnostic."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (15, 'rich_text', 'Choosing a Plan', '{"markdown":"Use your weeks available and the shape of your gap.\n\n| Weeks until test | Gap mostly in one section | Gap spread across both |\n|---|---|---|\n| About 4 | Four-week sprint, weighted to that section | Four-week sprint |\n| About 8 | Math priority or Reading and Writing priority | Eight-week standard |\n| 12 or more | Section-priority plan, then switch to standard | Twelve-week foundation |\n\n**If a section is below its benchmark, prefer the longer or section-priority option.** Foundations take time to build, and a sprint mainly sharpens existing skills."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (16, 'callout', 'No Promised Point Gains', '{"label":"Be wary of guaranteed improvements","body":"College Board does not publish an expected number of points per week of study, and the Playbook does not invent one. How much a score moves depends on your starting point, which domains are weak, how consistently you practise and how well you review mistakes. Treat any guarantee of a fixed gain, from anyone, as marketing rather than evidence, and judge your progress by your own repeated practice tests."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (17, 'rich_text', 'Plan Your Test Dates Backward', '{"markdown":"Pick dates first, then build the plan from them.\n\n1. **Find the application deadline** that matters most and the score-sending time you need before it. Weekend scores are typically released two to four weeks after the test, and sending them to colleges takes additional time.\n2. **Choose a main test date** that leaves room for that.\n3. **Choose a backup date** about one to three months later, still before the deadline. Knowing there is a second chance lowers pressure on the first.\n4. **Count the weeks** from today to the main date. That number, more than anything else, chooses your plan template.\n5. **Register early.** Test centres can fill, especially in busy months, and you need time to prepare your device in Bluebook.\n\n**Example:** if your deadline is early January and you need your score sent by mid-December, a test in early October with a backup in early November or December works. If today is mid-August, you have about seven weeks: the eight-week standard plan, slightly compressed."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (18, 'rich_text', 'Balancing the SAT With School', '{"markdown":"The SAT rewards the same habits as good schoolwork, but it competes for the same hours.\n\n- **Protect your grades.** Most admissions decisions weigh your school record heavily. Do not let SAT preparation damage it.\n- **Use short sessions on school days.** Thirty to forty-five focused minutes beat two distracted hours.\n- **Put long sessions on weekends.** Full-length tests and long reviews fit better there.\n- **Plan around exam weeks.** Reduce SAT hours during school exams and increase them afterward, rather than abandoning the plan.\n- **Sleep is part of the plan.** Tired practice produces careless errors that teach you the wrong lessons."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (19, 'rich_text', 'How Many Hours a Week?', '{"markdown":"There is no official formula linking hours to points, and anyone who promises a fixed number of points per hour is guessing. What you can control is consistency and quality.\n\n- **Minimum useful rhythm:** about four to five focused hours a week, spread across at least four days.\n- **Typical serious preparation:** about six to ten hours a week.\n- **Intensive short runway:** up to about twelve to fifteen hours a week for a few weeks, if school allows, with rest built in.\n\nMore important than the total: **every week includes targeted skill work, at least one timed set per section, and an error-log review.** A week of only full tests measures you; it rarely improves you."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (20, 'rich_text', 'A Sample Week', '{"markdown":"A balanced **eight-hour week** for a student following the eight-week standard plan:\n\n| Day | Session | Time |\n|---|---|---|\n| Monday | Weakest Math domain: module section + 15 bank questions | 60 min |\n| Tuesday | Weakest R&W domain: module section + 15 bank questions | 60 min |\n| Wednesday | Timed Math module (22 questions, 35 minutes) + review | 75 min |\n| Thursday | Second weakest domain, mixed difficulty | 60 min |\n| Friday | Timed R&W module (27 questions, 32 minutes) + review | 75 min |\n| Saturday | Full-length test every other week; otherwise mixed hard set | 150 min |\n| Sunday | Error log: redo every missed question from the week | 45 min |"}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (21, 'rich_text', 'Tracking Progress', '{"markdown":"Measure on a schedule, not when you feel like it.\n\n- **Full-length test:** every one to two weeks once skill work is under way, always under real conditions.\n- **Domain check:** every week, look at your accuracy by domain in SAT Practice. Domains that are not improving need a different approach, not just more questions.\n- **Error log:** count errors by type (content gap, misread, timing, careless). The mix tells you whether to study, slow down or practise pacing.\n- **Trend, not single points:** compare the average of your last two tests with the previous two. Individual tests vary."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (22, 'rich_text', 'When to Adjust the Target', '{"markdown":"Adjust when the evidence is clear, not after one test.\n\n- **Raise the target** if your last two full tests are both at or above it with time remaining before the test date.\n- **Keep the target and extend the timeline** if you are improving steadily but will not reach the target by the planned date; consider a later test date or a planned retake.\n- **Change the plan, not the target,** if one domain refuses to move after two to three weeks of focused work: try a different method, a tutor, or a different practice source.\n- **Revisit college requirements** each year; published ranges change."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (23, 'rich_text', 'Common Goal-Setting Traps', '{"markdown":"- **Choosing a number because it sounds impressive.** Tie the target to an actual requirement.\n- **Ignoring section targets.** A total target hides which section needs the work.\n- **Reading one practice score as a verdict.** Use a baseline from at least two tests.\n- **Expecting linear improvement.** Progress is uneven; plateaus are normal before jumps.\n- **Planning without a test date.** Without a date, preparation drifts. Pick a first date and a possible retake date now.\n- **Comparing with friends.** Their starting point, targets and timeline are not yours."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (24, 'rich_text', 'Drill: Read the Data', '{"markdown":"Use the tables in this module.\n\n1. A student scores 1300. About what user-group percentile is that?\n2. Which is a higher user-group percentile: 650 in Reading and Writing or 650 in Math?\n3. A student''s two practice tests are 1180 and 1220. What baseline should they plan from?\n4. A target university publishes a middle 50% of 1290 to 1450. What target follows the \"aim near the 75th percentile\" rule?\n5. A student has Reading and Writing 450 and Math 600. Which section is below its college readiness benchmark?\n6. About what share of the class of 2025 scored 1200 or higher?"}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (25, 'rich_text', 'Drill Answers and Explanations', '{"markdown":"1. **About the 85th percentile.** The table lists 1300 at 85 for the user group (91 nationally representative).\n2. **They are the same.** Both are listed at the 84th user-group percentile.\n3. **About 1200.** The average of 1180 and 1220 is 1200; treat it as a range around that value.\n4. **About 1450.** That is the 75th percentile of the published range. Scoring there makes the score a strength rather than a neutral factor.\n5. **Reading and Writing.** The benchmark is 480, so 450 is below it; Math 600 is above its 530 benchmark.\n6. **About 25%.** The 1400–1600 band (7%) plus the 1200–1390 band (18%)."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (26, 'rich_text', 'Frequently Asked Questions', '{"markdown":"### What is a good SAT score?\nA good score is one that meets the requirements of the places you are applying to. Nationally, College Board''s user-group table puts 1200 at about the 75th percentile and 1400 at about the 93rd.\n\n### Should I use user or nationally representative percentiles?\nFor admissions comparisons, the user group is usually more relevant, because it compares you with students who actually took the SAT.\n\n### Is my practice test score reliable?\nOfficial and well-built practice tests give useful estimates, but every score has a margin. Use the average of recent tests as your baseline.\n\n### Can I set different targets for different colleges?\nYes. Plan for the highest target that matters to you, then you are covered for the others.\n\n### How far in advance should I start?\nCollege Board suggests taking the SAT at least twice, in the spring of the junior year and the fall of the senior year. Working back from your first date, eight to twelve weeks of steady preparation suits most students.\n\n### Do plan templates replace the domain modules?\nNo. Plans tell you what to do each week; the domain modules teach the skills the plans assign."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (27, 'rich_text', 'Related Practice', '{"markdown":"- [SAT Simulator](https://sat.schood.online): take a diagnostic and later progress tests.\n- [SAT Practice study plan](https://practice.sat.schood.online/plan): daily sets aligned with your goal.\n- [Today''s practice session](https://practice.sat.schood.online/today): a short mixed set to keep the habit going."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (28, 'rich_text', 'Next Steps', '{"markdown":"1. If you have not taken a diagnostic yet, take one in the [SAT Simulator](https://sat.schood.online).\n2. Open the plan template that fits your timeline, starting with the [eight-week standard plan](https://playbook.sat.schood.online/plans/eight-week-standard) if you are unsure.\n3. Read the domain module for your weakest domain, starting from [SAT Essentials](https://playbook.sat.schood.online/sat-essentials) if you need the overview.\n4. Decide your first and backup test dates with [Retake and Superscore Strategy](https://playbook.sat.schood.online/retake-and-superscore-strategy)."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb)
) as s(n, block_type, heading, content, metadata)
where p.id = md5('schood-sat-pb-page:score-goals-and-study-plans')::uuid
on conflict do nothing;

