-- Module 13: test-day-guide (28 sections, 3093 words) ------------
insert into public.sat_playbook_pages (id, product_id, parent_page_id, page_type, module_key, slug, title, summary, status, visibility, locale_code, sort_order, seo_title, seo_description, seo_keywords, published_at, metadata)
values (md5('schood-sat-pb-page:test-day-guide')::uuid, 'a8b41e2c-9a36-4caf-9bba-7212e35a8b8c'::uuid, null, 'module', 'test-day-guide', 'test-day-guide', 'SAT Test Day Guide', 'Everything for the digital SAT day itself: Bluebook setup deadlines, device and ID rules, what to bring and leave at home, the check-in timeline, break rules, what to do if your device fails, and the decisions you face after the test.', 'published', 'public', 'en', 13, 'Digital SAT Test Day Guide: Bluebook, Devices, ID and Check-In | SAT Playbook', 'Prepare for digital SAT test day with Bluebook setup deadlines, device and ID rules, a what-to-bring list, the check-in timeline, break rules and after-test deadlines.', array['SAT', 'SAT test day', 'Bluebook', 'SAT admission ticket', 'SAT ID requirements', 'what to bring SAT', 'Digital SAT', 'SAT Playbook']::text[], '2026-10-24T00:00:00Z'::timestamptz, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1","original_slug":"test-day-guide","module_group":"test_day_protocol","migration_group":"core","hero_kicker":"Module 13","word_count":3093,"section_count":28,"reading_minutes":15,"estimated_reading_minutes":15,"section_kinds":["rich_text","checklist","callout"],"related_practice":[{"label":"Full-length rehearsal in the SAT simulator","url":"https://sat.schood.online"},{"label":"Today''s practice session","url":"https://practice.sat.schood.online/today"}],"last_verified":"2026-10-24","verification_status":"verified","editorial":"original-schood"}'::jsonb)
on conflict do nothing;

insert into public.sat_playbook_page_sections (id, page_id, block_type, heading, status, sort_order, content, metadata)
select md5('schood-sat-pb-section:test-day-guide:' || s.n)::uuid, p.id, s.block_type, s.heading, 'published', s.n, s.content, s.metadata
from public.sat_playbook_pages p
cross join (values
  (1, 'rich_text', 'Why This Module Matters', '{"markdown":"Months of preparation can be undone by a flat battery, an ID that does not match your registration, or a phone left in your pocket. None of these problems is about the SAT itself, and all of them are avoidable.\n\nThe digital SAT adds a few new steps to test day: you must install Bluebook, complete exam setup, download an admission ticket and bring a working device. This guide walks through each step in order, from a month before the test to the week after it, using College Board''s current rules.\n\n**Rules can change, and your admission ticket is specific to your test.** Read College Board''s test-day pages and your own admission ticket in the final week, and follow them where they differ from anything here."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (2, 'checklist', 'What You Will Be Able to Do', '{"items":["Complete Bluebook installation, practice and exam setup on time.","Prepare an approved, fully charged device, or request a College Board device in time.","Bring every required item and leave every prohibited item at home.","Present an ID that meets the rules for where you are testing.","Follow the check-in steps and the test-day timeline calmly.","Use the break well and handle device or submission problems.","Know the after-test deadlines for cancelling scores and free score sends."]}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (3, 'rich_text', 'The Timeline at a Glance', '{"markdown":"| When | What to do |\n|---|---|\n| At least 30 days before | Download Bluebook, take a practice test in it, check your device; request a College Board device if you need one |\n| 5 days before | Complete exam setup in Bluebook and get your admission ticket |\n| The day before | Charge the device, pack your bag, check the route and arrival time |\n| Test morning | Final device check: open Bluebook, look for messages, close other apps |\n| At the test centre | Show ticket and ID, connect to the centre''s Wi-Fi, check in to Bluebook, enter the start code |\n| Within 7 days after | Decide on cancellation only if something went seriously wrong (deadline 11:59 p.m. ET one week after) |\n| Within 9 days after (weekend tests) | Use or change your free score sends |\n| About 2 to 4 weeks after | Most weekend scores are released |\n\n**The two dates people miss most often are the 30-day and 5-day marks.** Put both in your calendar the day you register."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (4, 'rich_text', 'A Month Before: Bluebook and Practice', '{"markdown":"Bluebook is College Board''s testing app. You take the SAT inside it, and you also use it to practise.\n\n1. **Download Bluebook at least 30 days before** test day on the device you will use.\n2. **Take a full-length practice test in Bluebook** on that same device. This checks the device and familiarises you with the tools: the timer, mark for review, option eliminator, highlights and notes, the question menu, the Desmos calculator and the reference sheet.\n3. **Use Test Preview** if you only want to try the tools quickly.\n4. **Practise with the calculator you will use** on test day, whether that is Bluebook''s built-in Desmos or your own approved handheld.\n\nStarting a month ahead gives you time to fix problems: an unsupported device, a school-managed laptop that needs settings changed, or a request for a loaner."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (5, 'rich_text', 'Your Testing Device', '{"markdown":"You need an **approved device with the correct settings**. College Board''s Bluebook site lists approved devices and has separate guides for personal devices and for school-managed Chromebooks, Windows and Apple devices.\n\n- **Battery:** your device should hold a charge for **3 to 4 hours**. Outlets are not guaranteed in the testing room, so bring a power cord or portable charger as well.\n- **School-managed devices:** your school may need to prepare the device for you. Ask early.\n- **No suitable device?** For weekend SAT administrations, you can request a device from College Board **at least 30 days before test day**. It is prepared and sent to your test centre. Students using a loaned device arrive earlier (see the timeline below).\n- **Accessories:** an external wired mouse is allowed if you use one. An external keyboard is allowed **only with tablets**, not laptops."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (6, 'rich_text', 'Five Days Before: Exam Setup and Admission Ticket', '{"markdown":"From five days before the test, Bluebook lets you complete **exam setup** for your specific test. When setup is finished, you can access your **admission ticket**.\n\n- **Complete setup on the device you will bring.**\n- **Get your admission ticket.** College Board prefers a printed copy. You can also photograph it or email it to yourself, but if you show it on a phone, remember that the phone will be collected before testing.\n- **Read the ticket.** It shows your test centre address and arrival time, which may differ from the general timeline.\n- **Check that your name on the ticket matches your ID exactly.**"}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (7, 'rich_text', 'Photo ID Rules', '{"markdown":"Your ID must be **valid, unexpired, original and physical**. Digital IDs, photocopies and documents on a device are not accepted. The photo must be recent and match your appearance, and the document must be in good condition with legible English text.\n\n- **Name match:** the name on your ID must match the full, legal name on your admission ticket. A nickname on one document and a full name on the other can lead to denial. Middle names and initials are optional.\n- **Testing outside your home country:** you must use a **valid passport** (the only exception College Board lists is a U.S. Department of War Common Access Card). Some countries have their own specific rules, published on College Board''s ID requirements page.\n- **Students aged 21 or older:** only an official government-issued photo ID is accepted.\n- **Keep your ID with you** throughout the test, including during the break. It is checked each time you enter the testing room.\n\n**For students in Uzbekistan or anywhere else:** check College Board''s ID page for your testing country before test day. If you are testing outside your home country, a valid passport is required; if you are testing at home and have a passport, it is usually the simplest document to bring. Fix any name mismatch with College Board Customer Service at least 30 days before the test."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (8, 'rich_text', 'What to Bring', '{"markdown":"The official must-bring list:\n\n- **Your testing device**, fully charged, with Bluebook installed and exam setup complete.\n- **Your admission ticket**, preferably printed.\n- **An acceptable photo ID** (physical, not electronic).\n- **Pencils or pens** for scratch work. Scratch paper is provided; do not bring your own.\n- **Your College Board username and password.**\n- **An acceptable calculator** if you want one; Bluebook''s built-in Desmos calculator is always available.\n- **Epinephrine auto-injectors** if needed, in a clear bag under your desk; contact College Board''s disability services for other medications or medical devices.\n\nNice to have:\n\n- **A watch without an audible alarm**, to time your break.\n- **A charging cable or portable charger.**\n- **A bag or backpack.**\n- **A drink and snacks for the break.**\n- **A backup testing device**, if you have one."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (9, 'rich_text', 'What to Leave at Home', '{"markdown":"College Board''s testing rules prohibit a long list of items in the testing room and during breaks. The main ones:\n\n- **Phones, smartwatches, smart glasses** or eyewear with internet or AI access, fitness trackers and other wearables.\n- **Headphones and earbuds**, even if switched off, unless you have an approved accommodation that requires wired, non-Bluetooth headphones.\n- **Cameras and recording or listening devices.**\n- **Stylus pens and smart pens.**\n- **Watches that beep or have alarms or timers.**\n- **Books, notes, reference guides, dictionaries, highlighters, coloured pencils, protractors and compasses.**\n- **Your own scratch paper** and detachable privacy screens.\n- **Prohibited calculators**, including CAS models, calculators with QWERTY keyboards and phone calculator apps.\n\nPhones are collected or stored according to the test centre''s process. If you bring one for the journey, be ready to hand it over or put it away completely."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (10, 'rich_text', 'Calculator Check', '{"markdown":"If you bring a handheld calculator:\n\n- It must be an **approved, battery-operated, non-CAS** calculator. Graphing and scientific calculators without CAS are allowed; four-function calculators are allowed but not recommended because they typically do not follow order of operations.\n- **Remove programs with algebra functionality** and any stored documents.\n- **Turn off all sound**, and keep covers under your desk.\n- **Bring fresh batteries.**\n- The calculator may be used **only on the Math section**; keep it under your desk during Reading and Writing.\n- **You cannot share** a calculator.\n\nIf your calculator fails, you can continue with Bluebook''s built-in Desmos, which is one reason to practise with it."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (11, 'rich_text', 'A Rehearsal Weekend', '{"markdown":"One or two weekends before the real test, run a full rehearsal so that nothing on the day is new.\n\n- **Start at the same time** as your real test, around 8:15 to 8:30 a.m., after the same breakfast you plan to eat.\n- **Use the same device and calculator**, unplugged, to confirm the battery lasts.\n- **Take a full-length timed test** in Bluebook or the [Schood SAT simulator](https://sat.schood.online), with a 10-minute break between sections and no phone.\n- **Pack the bag the night before** from the checklist below and time the journey to your test centre if you can.\n- **Review the result for process, not just score:** did you hit your pacing checkpoints, use the break well and answer every question?"}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (12, 'rich_text', 'Accommodations and Extended Time', '{"markdown":"Students with documented disabilities can request accommodations through College Board''s Services for Students with Disabilities, such as extended time, extra or extended breaks, text-to-speech or a small-group setting. Requests must be approved before test day, so start early.\n\n- **Finish times change** with extended time. College Board''s typical Saturday schedule shows time-and-one-half testing ending around 12:00 to 12:15 p.m. and double time around 1:00 to 1:15 p.m.\n- **Approved headphones:** students approved for the embedded text-to-speech accommodation may bring wired, non-Bluetooth headphones.\n- **Breaks as needed:** students with that accommodation pause the timer as instructed rather than using an unscheduled break.\n- **Practise with your accommodations** in Bluebook so the settings feel normal on the day."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (13, 'rich_text', 'The Night Before', '{"markdown":"- **Charge your device fully** and your portable charger.\n- **Open Bluebook** to make sure it starts and that exam setup shows as complete.\n- **Pack your bag** from the checklist in this module: device, charger, ticket, ID, pencils, calculator, watch, snack, drink.\n- **Check your route and the arrival time** on your admission ticket. Allow extra travel time.\n- **Stop studying early.** Light review is fine; a late-night practice test is not.\n- **Sleep.** It improves attention more than any last-minute study."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (14, 'rich_text', 'Test Morning', '{"markdown":"- **Eat a breakfast you are used to.**\n- **Do the final device check:** open Bluebook, and close and reopen it to pick up any last-minute messages or test centre updates.\n- **Close every other application** on your device before you enter the testing room. Other open applications can be detected and could put your scores at risk.\n- **Warm up for five minutes** with two or three easy questions you have already solved, just to switch your brain on.\n- **Leave early.** Doors close and late arrivals are not admitted once testing has started."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (15, 'rich_text', 'The Test-Day Timeline', '{"markdown":"College Board''s typical schedule for a Saturday morning SAT:\n\n| Time | What happens |\n|---|---|\n| 7:15 a.m. | Students using a College Board loaned device arrive |\n| 7:45 a.m. | Check-in begins for all students |\n| 8:00 a.m. | Doors close |\n| 8:15–8:30 a.m. | Testing starts |\n| about 10:45–11:00 a.m. | Standard-time testing ends |\n\n**Your admission ticket shows your actual arrival time**, which may differ. Students with approved extended time finish later."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (16, 'rich_text', 'Check-In Steps', '{"markdown":"1. **Show your admission ticket and photo ID** to staff.\n2. **Wait to be seated.** Seats are assigned.\n3. **Connect to the test centre''s Wi-Fi** shown by the staff. Do not connect to any other network.\n4. **Open Bluebook** and complete the short check-in in the app.\n5. **Listen to the proctor''s instructions.** Prohibited items are collected or put away, and the proctor checks any calculator you brought.\n6. **Enter the start code** when the proctor gives it. Your timer starts when you enter it, and each student is timed individually, so your break and end times may differ slightly from your neighbour''s.\n\nYou receive one sheet of scratch paper; write your name on it and ask for more if you need it. Proctors answer questions about procedure only, not about test content."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (17, 'rich_text', 'During the Test', '{"markdown":"- **Section 1 is Reading and Writing**: two modules of 27 questions, 32 minutes each.\n- **Section 2 is Math**: two modules of 22 questions, 35 minutes each.\n- **Within a module** you can move between questions and review answers until time runs out.\n- **When the module timer reaches zero,** Bluebook moves you on automatically. **You cannot return** to a module once it ends.\n- **The timer can be hidden**, and Bluebook alerts you when 5 minutes remain.\n- **Answer every question.** There is no penalty for wrong answers.\n\nFor pacing plans and checkpoints, see [Pacing and Adaptive Modules](https://playbook.sat.schood.online/pacing-and-adaptive-modules)."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (18, 'rich_text', 'The Break', '{"markdown":"There is **one 10-minute break between the two sections**.\n\n- **Leave your device open** during the break; follow the instructions on Bluebook''s break screen.\n- **Keep your ID with you.** It is checked when you return to the room.\n- **No phones, devices, notes or other resources** during the break.\n- **A calculator you brought stays on your desk.**\n- **Eat, drink and move.** A short walk and a snack help you start Math fresh.\n- **Return on time.** The break timer runs whether you are back or not.\n\nIf you need a break at another time, Bluebook has an unscheduled break option, but **the time you lose is not added back**. Students with an approved accommodation for breaks follow the instructions for their accommodation."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (19, 'callout', 'If Something Goes Wrong', '{"label":"Raise your hand early","body":"If Bluebook shows a low-battery warning, a connection problem or anything unexpected, raise your hand straight away and tell the proctor; you can also select the Help option in Bluebook for troubleshooting tips. Bluebook is built to save your work as you go, and if your device cannot continue, staff can help you switch to a backup device. Do not try to fix problems silently, and do not close your device until you are dismissed."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (20, 'rich_text', 'Device and Submission Problems in Detail', '{"markdown":"- **Low battery:** plug in if an outlet is available, or use your portable charger. Raise your hand if the warning appears.\n- **Connection drops:** Bluebook is designed to let you keep working if the internet connection drops; tell the proctor.\n- **Device fails completely:** you may be able to switch to a second device with staff help.\n- **Submission fails at the end:** your work is saved on your device. Follow the on-screen instructions, and tell the proctor if it keeps failing. If you have to leave without submitting, the answers must be submitted by the end of the following day.\n- **Do not close your device or leave** until the proctor confirms your answers are submitted and dismisses you."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (21, 'rich_text', 'Handling Nerves', '{"markdown":"Some nervousness helps focus. Too much narrows attention. A simple plan:\n\n- **Expect the first question to feel strange.** Answer it and move on; the rhythm arrives after a few questions.\n- **Use a reset breath** when you notice tension: breathe in slowly for four counts, out for six, then reread the question stem.\n- **Do not judge the test while you are taking it.** You cannot tell which Module 2 you received, and guessing about it only distracts you.\n- **Keep the plan small:** this question, then the next one.\n- **Use the break** to leave Reading and Writing behind completely."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (22, 'rich_text', 'After the Test', '{"markdown":"- **Scores:** most scores from weekend tests are released **two to four weeks** after test day. College Board publishes exact dates on its score release page, and you are notified by email.\n- **Cancelling scores:** only for a serious problem. The request must be made in your College Board account by **11:59 p.m. Eastern Time one week after the test date**, and it cannot be undone.\n- **Free score sends:** for weekend tests you can send scores to up to four organisations for free; use or change them **within nine days after the test**.\n- **Write down what happened** while you remember: timing, question types that felt hard, anything about the room or device. These notes are valuable if you decide to retake.\n\nRetake and score-sending decisions are covered in [Retake and Superscore Strategy](https://playbook.sat.schood.online/retake-and-superscore-strategy)."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (23, 'checklist', 'Countdown Checklist: Thirty Days Out', '{"items":["Bluebook is installed on the device I will use.","I have taken a full-length practice test in Bluebook on that device.","My device is approved and holds a charge for 3 to 4 hours, or I have requested a College Board device.","My name in my College Board account matches my ID exactly.","I know which calculator I will use and have practised with it."]}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (24, 'checklist', 'Countdown Checklist: Final Week', '{"items":["Exam setup is complete in Bluebook (available from five days before).","My admission ticket is downloaded and printed.","I have read the arrival time and test centre address on my ticket.","My photo ID is valid, physical and meets the rules for where I am testing.","My calculator, if I bring one, is approved, has fresh batteries and has no prohibited programs.","I have a plan for where my phone will go during the test."]}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (25, 'checklist', 'Countdown Checklist: Bag for Test Morning', '{"items":["Fully charged testing device with Bluebook ready.","Power cord or portable charger.","Printed admission ticket.","Acceptable physical photo ID.","Two pencils or pens.","College Board username and password.","Approved calculator, if using one.","Watch without an audible alarm.","Drink and snack for the break."]}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (26, 'rich_text', 'Frequently Asked Questions', '{"markdown":"### Can I use my phone to show my admission ticket?\nYou can show it on a phone at check-in, but the phone is then collected or stored. College Board prefers a printed copy.\n\n### Do I need to bring scratch paper?\nNo. Scratch paper is provided by the test centre, and you may not bring your own. Bring pencils or pens.\n\n### What if I arrive after the doors close?\nLate arrivals are not admitted once testing has started. Check the arrival time on your admission ticket and allow extra travel time.\n\n### Can I leave early if I finish a module quickly?\nNo. You stay for the full testing time and may not leave the room until staff dismiss you. Use extra time to review within the module.\n\n### Is the calculator allowed in Reading and Writing?\nNo. Calculators are for the Math section only; keep a handheld calculator under your desk during Reading and Writing.\n\n### What if my calculator stops working?\nUse Bluebook''s built-in Desmos calculator, which is available for the whole Math section."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (27, 'rich_text', 'Related Practice', '{"markdown":"- [SAT Simulator](https://sat.schood.online): rehearse a full-length, timed test at the same time of day as your real test.\n- Official full-length practice in Bluebook: take at least one on the device you will bring.\n- [Today''s practice session](https://practice.sat.schood.online/today): light practice in the final days instead of new topics."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (28, 'rich_text', 'Next Steps', '{"markdown":"1. Rehearse your timing plan with [Pacing and Adaptive Modules](https://playbook.sat.schood.online/pacing-and-adaptive-modules).\n2. Make the calculator automatic with [Desmos and Calculator Strategy](https://playbook.sat.schood.online/desmos-and-calculator-strategy).\n3. Plan your next sitting and score sends with [Retake and Superscore Strategy](https://playbook.sat.schood.online/retake-and-superscore-strategy).\n4. Revisit [SAT Essentials](https://playbook.sat.schood.online/sat-essentials) for a final review of the format."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb)
) as s(n, block_type, heading, content, metadata)
where p.id = md5('schood-sat-pb-page:test-day-guide')::uuid
on conflict do nothing;

