-- Module 14: retake-and-superscore-strategy (28 sections, 3142 words) ------------
insert into public.sat_playbook_pages (id, product_id, parent_page_id, page_type, module_key, slug, title, summary, status, visibility, locale_code, sort_order, seo_title, seo_description, seo_keywords, published_at, metadata)
values (md5('schood-sat-pb-page:retake-and-superscore-strategy')::uuid, 'a8b41e2c-9a36-4caf-9bba-7212e35a8b8c'::uuid, null, 'module', 'retake-and-superscore-strategy', 'retake-and-superscore-strategy', 'Retake and Superscore Strategy', 'When a retake makes sense, how Score Choice and superscoring actually work, how free score sends and cancellation deadlines affect your decisions, and how to prepare differently for a second or third sitting.', 'published', 'public', 'en', 14, 'SAT Retakes, Score Choice and Superscoring Explained | SAT Playbook', 'Decide whether to retake the SAT, understand Score Choice and superscore policies, use free score sends and cancellation deadlines wisely, and plan a focused retake.', array['SAT', 'SAT retake', 'SAT superscore', 'Score Choice', 'send SAT scores', 'cancel SAT scores', 'Digital SAT', 'SAT Playbook']::text[], '2026-10-24T00:00:00Z'::timestamptz, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1","original_slug":"retake-and-superscore-strategy","module_group":"result_strategy","migration_group":"core","hero_kicker":"Module 14","word_count":3142,"section_count":28,"reading_minutes":16,"estimated_reading_minutes":16,"section_kinds":["rich_text","checklist","callout"],"related_practice":[{"label":"Full SAT simulator","url":"https://sat.schood.online"},{"label":"Hard Math questions","url":"https://practice.sat.schood.online/bank?section_type=math&difficulty=hard"},{"label":"Hard Reading and Writing questions","url":"https://practice.sat.schood.online/bank?section_type=reading_writing&difficulty=hard"}],"last_verified":"2026-10-24","verification_status":"verified","editorial":"original-schood"}'::jsonb)
on conflict do nothing;

insert into public.sat_playbook_page_sections (id, page_id, block_type, heading, status, sort_order, content, metadata)
select md5('schood-sat-pb-section:retake-and-superscore-strategy:' || s.n)::uuid, p.id, s.block_type, s.heading, 'published', s.n, s.content, s.metadata
from public.sat_playbook_pages p
cross join (values
  (1, 'rich_text', 'Why This Module Matters', '{"markdown":"Many students treat the SAT as a single high-stakes event. In practice, most applicants can take it more than once, choose which test dates to send, and benefit from colleges that combine their best section scores. Used well, those rules lower the pressure on any one sitting and let you aim each attempt at a specific weakness.\n\nUsed badly, they cost money, time and confidence: retaking with no change in preparation, sending scores a college did not need, or cancelling a score in panic and losing a result that would have helped.\n\nThis module explains the official rules accurately and then turns them into decisions: whether to retake, when, how to prepare differently, and what to send.\n\n**Rules change.** Everything here was checked against College Board''s pages at the time of writing, and college policies are set by each college. Always confirm both before you act."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (2, 'checklist', 'What You Will Be Able to Do', '{"items":["Explain Score Choice, superscoring and \"send all scores\" policies and how they differ.","Know the official deadlines for free score sends and for cancelling scores.","Decide whether a retake is worth it using your target, your scores and your timeline.","Choose a second test date that leaves time for preparation and score sending.","Build a retake plan that targets the section or domains with the most room.","Avoid the common mistakes that waste a sitting."]}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (3, 'rich_text', 'How Many Times Can You Take the SAT?', '{"markdown":"College Board''s help centre states that there is **no limit** on the number of times a student can take the SAT. Its general advice is to take the test **at least twice**: in the spring of the junior year and the fall of the senior year. If you can only take it once, it suggests the spring of the junior year. The same page notes that most students score higher the second time.\n\nWhat that does not mean:\n\n- **It does not mean unlimited attempts are free of cost.** Each registration has a fee, and each attempt takes preparation time.\n- **It does not mean every college sees only your best score.** That depends on Score Choice and each college''s policy.\n- **It does not mean more attempts automatically raise scores.** A retake helps when preparation between sittings changes something."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (4, 'rich_text', 'Score Choice: What It Is', '{"markdown":"**Score Choice** lets you choose which test dates'' scores to send to each college or programme.\n\nThe key rules, from College Board''s score-sending pages:\n\n- **You choose by test date.** Scores from an entire SAT are sent together: your total and both section scores from that day.\n- **You cannot mix sections from different dates** in a single report. You cannot send only the Math score from one date and only the Reading and Writing score from another.\n- **Colleges cannot opt out of Score Choice.** It is a feature for students.\n- **Some colleges require all scores.** Score Choice still exists, but following that college''s policy means sending every test date.\n\nWhen you order score sends, the sending tool shows each selected institution''s stated requirements."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (5, 'rich_text', 'Superscoring: What It Is', '{"markdown":"**Superscoring** is a college policy, not a College Board product. A college that superscores combines your **highest Reading and Writing section score** and your **highest Math section score** across the test dates you send, even if they came from different sittings, to form a new total.\n\n**Example:** you send two test dates.\n\n| Test date | Reading and Writing | Math | Total |\n|---|---|---|---|\n| March | 650 | 610 | 1260 |\n| June | 620 | 680 | 1300 |\n| Superscore | 650 | 680 | 1330 |\n\nA college that superscores would consider 1330. A college that uses your highest single sitting would consider 1300. A college that reviews all scores would see both dates in full.\n\nMany superscoring colleges encourage or require applicants to send all scores, so they can identify the highest section scores consistently."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (6, 'rich_text', 'The Common College Policies', '{"markdown":"| Policy | What the college considers | What you should send |\n|---|---|---|\n| Superscore | Highest section scores across all dates sent | Usually every date that contains a best section score; follow any \"send all\" instruction |\n| Highest single sitting | The best total from one date | That date |\n| All scores required | Every sitting | Every test date |\n| Test optional | Scores if you choose to submit | Send only if your score helps your application |\n| Test required | A score is needed | Your best date, or all dates if required |\n\n**Policies vary by college and sometimes by programme or year.** Find the policy on the college''s own admissions website, usually under application requirements."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (7, 'rich_text', 'Free Score Sends and Their Deadline', '{"markdown":"For weekend SAT registrations, College Board allows score sends to **up to four organisations for free**. You can choose them at registration or any time before the test.\n\n- To use or change those free sends, you must act **within nine days after the test**. After that, sends carry a score reporting fee.\n- For SAT School Day testing, free sends are chosen during exam setup or **within three days after testing**, as your school instructs.\n- Students with a fee waiver can send scores without that fee.\n\nThe trade-off: free sends go out before you see your scores. If you are confident the test went well, or the colleges superscore or require all scores anyway, using free sends saves money. If you would rather see your scores first, you can send later and pay the fee."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (8, 'rich_text', 'How Long Score Sending Takes', '{"markdown":"- **Scores release:** most scores from weekend tests are released **two to four weeks** after test day; College Board publishes exact dates on its score release page.\n- **Standard delivery:** electronic delivery to colleges typically takes **5 to 10 business days** after you place the order, or about a couple of weeks after test day if you chose recipients at registration.\n- **Rush delivery:** available only for scores that have already been released, typically **1 to 4 business days**, excluding weekends and holidays.\n\nCount these delays backward from each application deadline before you choose a test date."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (9, 'rich_text', 'Cancelling Scores', '{"markdown":"You can cancel scores voluntarily, but the rules are strict:\n\n- The request must be submitted **through your College Board account** by **11:59 p.m. Eastern Time one week after your test date**.\n- **Cancellation is irreversible.** Once submitted, the scores cannot be reinstated or reported to you or to any institution.\n\nWhen to consider it: only if something went seriously wrong, such as illness during the test, and you are certain you would not want any college to see the result. Because of Score Choice, a weak score from a test date you never send is usually harmless for colleges that do not require all scores. **Cancelling also means you never learn what the score was**, which removes useful diagnostic information."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (10, 'rich_text', 'Score Sends Held', '{"markdown":"If **Score Sends Held** appears on a score report, College Board was unable to confirm that a complete set of responses was available when the test was scored. Incomplete responses could affect scores, and College Board does not report those scores to colleges unless you ask it to. If you see this, read the instructions on your report and contact College Board before making retake decisions."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (11, 'rich_text', 'Should You Retake? A Decision Framework', '{"markdown":"Work through these questions in order.\n\n1. **Is your score below the target that matters?** Compare it with the published middle 50% of your main target and any scholarship minimum. If you are already at or above the 75th percentile there, a retake is rarely the best use of your time.\n2. **Is there a realistic path to improve?** Compare the real score with your recent practice tests. If the real score is noticeably below your practice average, nerves, pacing or an unusual day may explain it, and a retake has a good chance of helping. If it matches your practice scores, you need new preparation, not just a new date.\n3. **Is there time?** You need a date that allows preparation and still lets scores reach colleges before deadlines.\n4. **What do the colleges do with multiple scores?** Superscoring colleges make a section-focused retake especially valuable.\n5. **What else needs your time?** School grades, applications and essays also matter. A retake that damages them is a poor trade.\n\nIf the answers to the first three are yes, plan the retake."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (12, 'rich_text', 'Choosing the Retake Date', '{"markdown":"- **Leave enough preparation time.** Six to ten weeks between sittings lets you work on real weaknesses; a very short gap mainly tests whether the first result was an off day.\n- **Respect the deadline chain.** Score release (two to four weeks) plus delivery (often 5 to 10 business days) must fit before each application deadline.\n- **Register early** to secure a convenient test centre and to have time to prepare your device in Bluebook.\n- **Avoid exam-heavy weeks at school** if you can."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (13, 'rich_text', 'Preparing Differently for a Retake', '{"markdown":"A retake works when it targets what the first sitting revealed.\n\n1. **Read your score report by domain.** The eight content domain bars show where you lost the most ground.\n2. **Prioritise by weight and gap.** A weak Algebra or Advanced Math domain matters more than a weak Geometry domain because of question counts.\n3. **Fix the failure type.** If you ran out of time, rebuild pacing (see [Pacing and Adaptive Modules](https://playbook.sat.schood.online/pacing-and-adaptive-modules)). If errors were careless, add a checking routine. If content was missing, study it with the domain modules.\n4. **Take at least two full-length practice tests** before the retake under real conditions.\n5. **Rehearse test day.** Many second attempts improve simply because the format and the room are familiar."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (14, 'callout', 'Verify Before You Rely on It', '{"label":"The college''s own page is the final word","body":"Score-use policies are set by each college, sometimes by each programme within it, and they can change between application cycles. A ranking site, a forum post or last year''s brochure is not a reliable source. Before you plan a retake around superscoring or decide which dates to send, open each college''s admissions page and note the policy and the date you checked it."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (15, 'rich_text', 'The Week After a Test', '{"markdown":"The first seven days after a sitting contain the two decisions with hard deadlines.\n\n1. **Days 1 to 2: write down what happened** while it is fresh: where you ran short of time, which question types felt hard, anything about the room or device. This is diagnostic gold for a retake.\n2. **By day 7: decide about cancellation.** In almost every case the answer is no. Cancel only for a serious problem, and remember it is irreversible.\n3. **By day 9: finalise free score sends** for a weekend test, if you plan to use them.\n4. **Then wait for scores** before deciding on a retake. Your notes plus the domain report make the decision far more accurate than your feeling on the day."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (16, 'rich_text', 'An Eight-Week Gap Between Sittings', '{"markdown":"A typical retake gap of about eight weeks can be used like this:\n\n| Weeks | Focus |\n|---|---|\n| 1 | Read the score report by domain; pick the priority section and two priority domains |\n| 2–4 | Skill rebuilding in the priority domains with the Playbook modules and filtered bank sets |\n| 5 | First full-length practice test; adjust priorities from the result |\n| 6–7 | Timed module-length sets, pacing checkpoints, error-log reviews |\n| 8 | Second full-length test early in the week, then light review and rest |\n\n**Keep the other section warm** with one timed set a week throughout. Many students lose a few points in their stronger section by ignoring it completely between sittings."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (17, 'rich_text', 'Section-Focused Retakes for Superscoring Colleges', '{"markdown":"If your colleges superscore, you can plan each sitting around one section without ignoring the other.\n\n- **Choose the section with the most room.** Look at the gap to your section target and at the percentile tables: points are often easier to find where your domain results show clear, learnable gaps.\n- **Put most of your hours there**, roughly two-thirds to three-quarters, while keeping the other section warm with one timed set a week.\n- **Still take the whole test seriously.** You will sit both sections, and a higher score in either still helps.\n- **Remember that \"send all\" policies are common among superscoring colleges**, so every date will usually be visible."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (18, 'rich_text', 'Worked Example 1: Retake or Stop?', '{"markdown":"**Profile (fictional):** real SAT 1340 (Reading and Writing 680, Math 660). Practice average before the test: 1350. Main target''s middle 50%: 1300 to 1420. Application deadline in eight weeks.\n\n**Analysis:** the score is within the target''s range and matches practice. A retake could help, but eight weeks leaves little time once score release and delivery are counted.\n\n**Decision:** a retake is possible only on a date about four weeks away, with a focused sprint on Math. If that date is not available, stop testing and put the time into applications."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (19, 'rich_text', 'Worked Example 2: The Off Day', '{"markdown":"**Profile (fictional):** real SAT 1180 (Reading and Writing 610, Math 570). Practice average before the test: 1270. The student ran out of time in both Math modules.\n\n**Analysis:** the real score is well below practice, and the cause is identifiable: pacing. The underlying skills are likely stronger than the score shows.\n\n**Decision:** retake in six to eight weeks with a pacing-first plan: checkpoints, time caps, Desmos shortcuts for systems and quadratics, and two full timed tests. Use Score Choice to decide later which dates to send."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (20, 'rich_text', 'Worked Example 3: Building a Superscore', '{"markdown":"**Profile (fictional):** first SAT: Reading and Writing 700, Math 590, total 1290. Target colleges superscore. Target total: 1400.\n\n**Analysis:** Reading and Writing is already strong. Math has the larger gap, and the domain report shows weak Advanced Math.\n\n**Decision:** retake with a math-priority plan, about three-quarters of study time on Advanced Math and Algebra. If the next Math score reaches about 700, the superscore reaches 1400 even if Reading and Writing dips slightly."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (21, 'rich_text', 'Scholarships, Foundation Programmes and Early Deadlines', '{"markdown":"Retake planning is tighter when a scholarship or an early application round is involved.\n\n- **Scholarship minimums are often hard cut-offs.** If a scholarship needs a minimum total or section score, plan the first sitting early enough that a retake can still meet its deadline.\n- **Some programmes set their own score rules.** A scholarship may use a single sitting even when the university superscores. Read both policies.\n- **Early rounds move the whole chain forward.** Count back from the early deadline, not the regular one, when you choose dates.\n- **Keep a written timeline.** List each deadline, the latest useful test date before it, the expected score release date and the date you need to order score sends. Seeing it on one page prevents the most expensive mistake: a good retake score that arrives too late."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (22, 'rich_text', 'Common Retake Mistakes', '{"markdown":"- **Retaking with the same preparation.** A new date without a new plan rarely produces a new result.\n- **Booking the retake too soon** to make any real change.\n- **Ignoring college policies.** Assuming every college superscores, or that none require all scores.\n- **Using free sends without thinking.** Decide deliberately whether you want scores sent before you see them.\n- **Panic cancelling.** Cancelling is irreversible and usually unnecessary because of Score Choice.\n- **Testing too many times.** Each sitting costs preparation time that applications and grades also need."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (23, 'checklist', 'Retake Planning Checklist', '{"items":["I compared my score with the published ranges of my target colleges.","I compared my real score with my recent practice test average.","I checked each college''s score-use policy on its own website.","I picked a retake date that leaves time for preparation, score release and delivery.","I read my score report by domain and chose my priority section and domains.","I decided how I will use my free score sends for the next sitting.","I know the cancellation deadline is 11:59 p.m. ET one week after the test date.","I scheduled at least two full-length practice tests before the retake."]}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (24, 'rich_text', 'Drill: Apply the Rules', '{"markdown":"1. A student has Reading and Writing 620 and Math 700 in May, and Reading and Writing 670 and Math 660 in October. What is the superscore?\n2. Can the student send only the October Reading and Writing score and the May Math score in one report?\n3. A weekend test is on a Saturday. Until when can free score sends be used or changed?\n4. A student wants to cancel. When is the latest they can do it?\n5. A college says it requires all scores. Does Score Choice let the student hide a date from that college?\n6. A student''s real score is 1210 and their practice average is 1220. Their target is 1350. What does this suggest about a retake?"}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (25, 'rich_text', 'Drill Answers and Explanations', '{"markdown":"1. **1370.** Highest Reading and Writing is 670 (October) and highest Math is 700 (May).\n2. **No.** Score Choice works by test date and sends whole score reports. A superscoring college forms the combination itself from the full dates you send.\n3. **Within nine days after the test.** After that, sends carry the score reporting fee.\n4. **By 11:59 p.m. Eastern Time one week after the test date**, through the College Board account. It cannot be undone.\n5. **Technically Score Choice still exists, but following the college''s policy means sending every date.** Colleges cannot switch off Score Choice, yet their admissions requirements still apply to you.\n6. **A retake helps only with new preparation.** The real score matches practice, so the skills, not the day, set the result. A targeted plan is needed before booking another date."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (26, 'rich_text', 'Frequently Asked Questions', '{"markdown":"### Will colleges see that I took the SAT several times?\nOnly the test dates you send, unless a college''s policy requires you to send all of them.\n\n### Is superscoring the same as Score Choice?\nNo. Score Choice is your option to choose which dates to send. Superscoring is a college''s method of combining section scores from the dates it receives.\n\n### Does taking the SAT many times look bad?\nCollege Board does not limit attempts, and colleges that require all scores see every attempt. Two or three well-prepared sittings are common; many more than that usually suggest preparation should change rather than dates.\n\n### Can I cancel only one section?\nCollege Board''s cancellation process applies to the scores from a test date. Read the cancellation agreement in your account carefully before you submit, because cancellation is irreversible.\n\n### When are scores released?\nMost weekend test scores are released two to four weeks after test day. College Board publishes exact release dates for each administration.\n\n### Should I send scores before I see them?\nUse free sends when you are confident, or when your colleges superscore or require all scores anyway. Otherwise, you can wait and pay the fee to send later."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (27, 'rich_text', 'Related Practice', '{"markdown":"- [SAT Simulator](https://sat.schood.online): rebuild your baseline with full-length tests between sittings.\n- [Hard Math questions](https://practice.sat.schood.online/bank?section_type=math&difficulty=hard) and [hard Reading and Writing questions](https://practice.sat.schood.online/bank?section_type=reading_writing&difficulty=hard): close the gap in your priority section.\n- [Today''s practice session](https://practice.sat.schood.online/today): keep the other section warm."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (28, 'rich_text', 'Next Steps', '{"markdown":"1. Reset your target with [Score Goals and Study Plans](https://playbook.sat.schood.online/score-goals-and-study-plans).\n2. If timing was the problem, read [Pacing and Adaptive Modules](https://playbook.sat.schood.online/pacing-and-adaptive-modules).\n3. Open the domain module for the weakest bar on your score report, beginning with [SAT Essentials](https://playbook.sat.schood.online/sat-essentials) for the domain list.\n4. Before the retake, review the [Test Day Guide](https://playbook.sat.schood.online/test-day-guide)."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb)
) as s(n, block_type, heading, content, metadata)
where p.id = md5('schood-sat-pb-page:retake-and-superscore-strategy')::uuid
on conflict do nothing;

