  ('https://satsuite.collegeboard.org/scores/sending-sat-scores/weekend', 1, 'Primary source for free score sends, Score Choice by test date and superscoring institutions', true),
  ('https://satsuite.collegeboard.org/help-center/how-many-times-can-student-take-sat-and-when-should-they-take-it', 2, 'No limit on attempts and recommended timing', false),
  ('https://satsuite.collegeboard.org/help-center/can-colleges-opt-out-score-choice', 3, 'Colleges cannot opt out of Score Choice; some require all scores', false),
  ('https://blog.collegeboard.org/what-is-an-sat-superscore', 4, 'What a superscore is and checking each college''s policy', false),
  ('https://satsuite.collegeboard.org/digital/cancel-scores', 5, 'Cancellation deadline, method and irreversibility', false),
  ('https://satsuite.collegeboard.org/sat/testing-rules', 6, 'Testing rules on voluntary cancellation and incomplete tests', false),
  ('https://satsuite.collegeboard.org/scores/score-release-dates', 7, 'Score release timing', false),
